UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Priority Delivery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the forgotten loot from the Lich King and find its intended recipient at the Steam Pools in Feralas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An adventurer of another time has forgotten to loot something big... something that might cause them great emotional strain if not received quickly.$B$BYour destination is Icecrown Citadel, your target the Lich King\'s corpse. Retrieve the missing item post-haste and deliver it to the stalwart adventurer - he should be somewhere at the Steam Pools in Feralas.$B$BMy assistant will open a portal to deliver you there. Just a moment!', `QuestDescription`) WHERE `ID` = 41367;
UPDATE `quest_template` SET `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Deliver the Lost Mail to Madam Goya in Dalaran Underbelly.', `QuestCompletionLog`) WHERE `ID` = 41368;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Service with a Smile', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sell Invincible\'s Reins to Gott Weedlespan for Johnny Awesome.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, simple $r. Simple, simple $r.$B$BI did not \'forget\' to sweep up those reins from that foolish cakewalk of a knight they call the Lich King. I simply did not bother, as I already received the mighty steed during my raid last week.$B$B<Johnny motions to the horse on his left.>$B$BSince you\'re here and clearly intrigued by my sweltering greatness, won\'t you take that superfluous stallion to the assistant resort director in town? My coffers could use a bit of extra lining.', `QuestDescription`) WHERE `ID` = 41394;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Due Reward', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place Twinkles\' favorite toy by his grave at the Sludge Fields in Hillsbrad Foothills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have served me well these past few minutes we\'ve spent together - minutes I shall not soon forget.$B$BI believe a reward befitting your unwavering loyalty is in order. You will have the distinct honor of placing Twinkles\' favorite toy by his grave in honor of his memory.$B$BPlease, please - save your thanks for Twinkles; it is not every day that we may honor a horse made of STARS.', `QuestDescription`) WHERE `ID` = 41395;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Huge Package', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver 1,362 pieces of solid stone to the Ethereal Portal in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Due to the incredible volume of complaints in recent months we have been barred from delivering s... s...$B$B<The Postmaster holds back tears, pain visible in his eyes.>$B$BSolid stone. We\'re positively swimming in it - if we can\'t deliver it then pretty soon we will be overwh-$B$B<The Postmaster\'s eyes light up suddenly.>$B$BThat\'s it!$B$BThere is an old Consortium portal not far from here that we could deposit it in with none the wiser!$B$BCan you help, $n? The stone is extraordinarily heavy.', `QuestDescription`) WHERE `ID` = 41397;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Walking in Their Footsteps', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Water of Vision to walk in the memories of Igrul the Scalebane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past.nnThe wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them.nnIgrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.', `QuestDescription`) WHERE `ID` = 41764;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Minions of the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Water of Vision to walk in the memories of Oenia Skyhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us.nnEbonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness.nnUse the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.', `QuestDescription`) WHERE `ID` = 41799;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Servants of the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Water of Vision to walk in the memories of Huln Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The heroes of Highmountain\'s past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years.nnWe must not fail their memory.nnHuln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn.nnEnter the echo of Huln\'s spirit, and let his courage lead you to the location of this ward.', `QuestDescription`) WHERE `ID` = 41800;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Curse of the Necrodark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Journey to Highmountain Summit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys.nnThey will not take our sacred mountain, $n. Not while I draw breath.nnWith the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all.nnCome. Let us take back the summit from the forces that would corrupt it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Rendezvous with Baine Bloodhoof at Highmountain Summit.', `QuestCompletionLog`) WHERE `ID` = 41815;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ice and Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Shadowice Shards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence.nnPerhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets.nnI know little of such magics, but it seemed that Ebonhorn had a use for them in mind.', `QuestDescription`) WHERE `ID` = 41840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Ward', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Restore the Summit Ward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Necrodark are readying their ritual to give physical form to the Darkness. They\'ve sealed themselves inside and barred our way.nnThe shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest.nnDo not hesitate. The fate of Highmountain itself hangs in the balance.', `QuestDescription`) WHERE `ID` = 41841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers of the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free $1oa Highmountain Protectors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into.nnOur people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own.nnWake them from their stupor. Free them from the whispers any way you can.', `QuestDescription`) WHERE `ID` = 41882;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Tales', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Spiritwalker Graysky in Riverbend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Spiritwalker Ebonhorn is stable... for now.nnHe once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own.nnIncapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack.nnTo find the wards, we must enter the echoes of Ebonhorn\'s past and commune with the spirits we find there.nnMeet me in Riverbend, $n. It is there our search begins.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Spiritwalker Graysky in Riverbend.', `QuestCompletionLog`) WHERE `ID` = 41884;
UPDATE `quest_template` SET `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Tyrosus.', `QuestCompletionLog`) WHERE `ID` = 42120;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Champion\'s Call [WIP]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '[PH] Interact with the Mission Table and complete "The Dalaran Situation."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] Greetings, $c. Beside me is the Mission Table. From it, you can assign our troops to complete vital assignments across the Broken Isles.$B$BGive it a try now, master. We have received word of a small demon attack on the city of Dalaran. Let us send someone to help repel the enemy.$B$BGaze upon the Mission Table and send a Champion to Dalaran.', `QuestDescription`) WHERE `ID` = 42143;
