UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mathias Visit Not Active 04', `LogTitle`) WHERE `ID` = 44199;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Depleted Nether Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the crystal to the Council of Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This crystal looks like something used in rituals of dark magic. Given that its energy is depleted, whoever this belongs to must have been successful in whatever ritual they were performing.nnThe mages of the Kirin Tor would likely be interested in investigating this.', `QuestDescription`) WHERE `ID` = 45052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thief\'s Instructions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the instructions to the Council of Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The hastily scrawled note reads:nn"I require the Focusing Iris for one of my spells. Show that you are truly the greatest of my apprentici and fetch it for me.nnOh, and make sure you don\'t leave this note lying around for some adventurer to find!"nnIf someone is looking to steal the Focusing Iris, the Kirin Tor will likely want to know.', `QuestDescription`) WHERE `ID` = 45053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '"Ancient" Elven War Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the forged orders to the Council of the Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These orders look official and bear the Ravencrest sigil, but they are far too new. There is also a hint of fel magic glimmering around the sides.nnThe Council of Six would be interested in seeing this.', `QuestDescription`) WHERE `ID` = 45054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Infused Totem Fragment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the totem fragment to the Council of the Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once!', `QuestDescription`) WHERE `ID` = 45059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Damaged Kirin Tor Insignia', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the insignia to the Council of the Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. nnThe Council of Six would no doubt be interested in this finding.', `QuestDescription`) WHERE `ID` = 45060;
UPDATE `quest_template` SET `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The book is a register of the inhabitants of Glenbrook.$b$bAll but a few of the names are crossed out.>', `QuestDescription`) WHERE `ID` = 45079;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Begin the Assault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Begin the assault on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn.nnNow we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. nnOur first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, $n. The assault on the Broken Shore begins now.', `QuestDescription`) WHERE `ID` = 45102;
