UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Sender', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return $1oa Rejected Letters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve arrived just in time!$B$BUnlike the mail as of late, I\'m afraid.$B$BWe are severely understaffed, and demand is at an all-time high. We simply can\'t keep up!$B$BI\'d love to chat, but I need help catching up before I can rest for even a moment.$B$BFirst thing\'s first. Several parcels of rejected mail have broken loose again; will you help me round them all up and return them to their senders?', `QuestDescription`) WHERE `ID` = 46278;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Further Advancement', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Sir Alamande Graythorn', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As the war against our enemies progresses, so must we.nnWe are now able to perform new research. Seek out Sir Alamande Graythorn to continue advancing the Order Hall.', `QuestDescription`) WHERE `ID` = 46787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Boon of the Mage Tower', `LogTitle`) WHERE `ID` = 47010;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Feast for Our Kin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Baine Bloodhoof at Thunder Bluff in Mulgore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion.nnAre you interested in hearing how they joined the Horde? It is quite the tale!nnIt all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Baine Bloodhoof at Thunder Bluff in Mulgore.', `QuestCompletionLog`) WHERE `ID` = 48066;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadow Over Thunder Bluff', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Dark Tendrils and $2oa Shadows of Uul in Thunder Bluff.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A dark force has descended upon us. I refuse to believe that the Highmountain are behind it.nnThe cacophony out there is disturbingly familiar. Could it be... nnNo! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, $n!', `QuestDescription`) WHERE `ID` = 48067;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Mayla Highmountain at Thunder Totem in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid.nnLet us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Mayla Highmountain at Thunder Totem in Highmountain.', `QuestCompletionLog`) WHERE `ID` = 48079;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadow of the Sepulcher', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Spiritwalker Graysky in Sepulcher of the Sky.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this "Darkness" once manifested.nnMeet me there, $n. I will show you how to walk in the memories of a great Skyhorn hero.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Spiritwalker Graysky in Sepulcher of the Sky.', `QuestCompletionLog`) WHERE `ID` = 48185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s Mountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Spiritwalker Graysky at Snowblind Mesa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have made progress reactivating the wards, but more must be done.nnI sense Ebonhorn\'s struggle. Though he fights with all his strength, he is slipping away. Should this "Darkness" emerge into our realm, I fear our friend will be lost.nnEbonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Spiritwalker Graysky at Snowblind Mesa.', `QuestCompletionLog`) WHERE `ID` = 48190;
