UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Unmaker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Argus the Unmaker in Antorus, the Burning Throne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Argus is Sargeras\' solution for existence; an end to all things. For everyone that might ever live, bring an end to the Unmaker.', `QuestDescription`) WHERE `ID` = 48306;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Uul\'gyneth the Darkness.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For thousands of years, the Darkness was held at bay. The wards stood... protecting Highmountain.nnNow they are gone, and evil is free once more.nnThe Darkness that haunted our dreams... that even the kobolds spoke of only in frightened whispers... has come.nnUul\'gyneth, herald of the Old Gods, paves the way for his masters. Unless we stand together and defeat him, all is lost.nnYou must hold nothing back, champion. None of us can.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Uul\'gyneth', `PortraitGiverName`) WHERE `ID` = 48403;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Together We Are the Horde!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ji Firepaw at the Orgrimmar Embassy to hear the end of this tale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What began with a simple feast led to a battle against an ancient evil seeking to consume the world.nnMy kind of day!nnYour deeds have helped secure an alliance between Orgrimmar and Highmountain. These tauren will make a valuable addition to the Horde.nnThe Warchief will be pleased.', `QuestDescription`) WHERE `ID` = 48433;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'How Fares Ebonhorn?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Thunder Totem and check on Ebonhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Three of the ancient wards are restored. The mountain is not yet secure, but we may have done enough to break Ebonhorn free of the shadows gripping him.nnLet us return to Thunder Totem and see how he fares. Hopefully Ebonhorn can tell us more about what is happening with the Necrodark and the insidious master they serve.', `QuestDescription`) WHERE `ID` = 48434;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Spires of Home', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Alleria Windrunner on the Isle of Quel\'Danas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My sister Vereesa told me of the events that led to the high... excuse me, "blood" elves joining the Horde.nnPart of me still can\'t accept it.nnPrince Kael\'thas led my people down a dark path. I have to believe the majority of sin\'dorei would shrug off the Horde if given the choice.nnThe last time I spoke to Lor\'themar, we served together in the Farstriders. He was a fine ranger and a good man. I pray the years have not changed that.nnCome. We must not keep the regent waiting.', `QuestDescription`) WHERE `ID` = 48489;
