UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Telogrus Rift', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Telogrus Rift and complete the scenario.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Umbric and his blood elves were cast out of their home for their pursuit of understanding.nnI know the dangers of the void better than most. We should lend them our aid and ensure they don\'t do anything too foolhardy.nnThis rift will take us to their current location. I hope we are not too late to help them.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Aysa Cloudsinger in Stormwind to hear the end of this tale.', `QuestCompletionLog`) WHERE `ID` = 48962;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Settle the Score', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Chartusk in Foxhollow Woods.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A year ago I lost my daughter to the largest boar in the forest.$b$bI have tracked him since, trading blows back and forth. But this time...$b$bLet\'s just say I don\'t have much time left.$b$bAll I wish for is vengeance. Please $c, avenge us so that my soul can leave this plane and join my daughter, wherever she may be.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'That beast will pay for taking my daughter\'s life.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Chartusk', `PortraitGiverName`) WHERE `ID` = 48965;
