UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forge of Aeons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bear witness to the ritual of the Lightforged.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lightforged have long stood as a beacon of hope against the Legion.nnBut few truly know what it takes to become the embodiment of Light\'s wrath.nnThese few champions among the Army of the Light are ready to undergo their final trial.nnWill you do us the honor of bearing witness?', `QuestDescription`) WHERE `ID` = 49266;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Remember the Sunwell', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the scenario, "Remember the Sunwell."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Regent Lord intends to show First Arcanist Thalyssra our Sunwell.nnI do not know if he will allow Alleria Windrunner to attend the meeting, but we are invited to join them.', `QuestDescription`) WHERE `ID` = 49354;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Shadowmoon Valley!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Blood Guard Gulmok at Shadowmoon Valley in Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Blood Guard Gulmok at Shadowmoon Valley in Outland.nnThe Burning Legion is attempting to lay siege to Shadowmoon Village, but our elite Kor\'kron force is showing them what it means to fight against the Horde.nnCrush the Legion.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Blood Guard Gulmok at Shadowmoon Valley in Outland.', `QuestCompletionLog`) WHERE `ID` = 49532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Howling Fjord!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Apothecary Lysander in Howling Fjord.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Apothecary Lysander in Howling Fjord.nnThe Forsaken have established a stronghold on the eastern shores of Northrend.nnNow is the time to strike at the Scourge with our military might and a new plague that is being developed by the Royal Apothecary Society.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Apothecary Lysander in Howling Fjord.', `QuestCompletionLog`) WHERE `ID` = 49533;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Zul\'Drak!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Crusader Lord Lantinga in Zul\'Drak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Crusader Lord Lantinga in Zul\'Drak.nnThe Scourge is massacring the local population in Zul\'Drak and converting them over to be part of the Scourge army.nnAssist the Argent Crusade and the Ebon Blade in stopping this threat.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Crusader Lord Lantinga in Zul\'Drak.', `QuestCompletionLog`) WHERE `ID` = 49534;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Sholazar Basin!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Archmage Pentarus in Dalaran over Crystalsong Forest.nnHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.nnWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49535;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Storm Peaks!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Rin Duoctane in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Rin Duoctane in Dalaran over Crystalsong Forest.nnThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.nnSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Rin Duoctane in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49536;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Icecrown!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Sky-Reaver Klum in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Sky-Reaver Klum in Dalaran over Crystalsong Forest.nnThe Warsong Offensive needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.nnIt is time to make the Lich King pay for his crimes.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Sky-Reaver Klum in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49537;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Jade Forest!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to General Nazgrim in Grommash Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to General Nazgrim in Orgrimmar.nnRecent victories in our naval battles against the Alliance strengthens our resolve.nnReport to Grommash Hold and assist the Horde\'s invasion fleet.nnFor the Horde!', `QuestDescription`) WHERE `ID` = 49538;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Valley of the Four Winds!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chen Stormstout in the Valley of the Four Winds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Chen Stormstout in the Valley of the Four Winds.nnThe adventuring spirit of the Stormstouts is something that the Horde can learn from.nnTravel with the Stormstouts and discover what secrets Pandaria holds.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Chen Stormstout in the Valley of the Four Winds.', `QuestCompletionLog`) WHERE `ID` = 49539;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Krasarang Wilds!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ken-Ken in Krasarang Wilds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Zhu\'s Watch in Krasarang Wilds.nnThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.nnSpeak with Ken-Ken at Zhu\'s Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Ken-Ken in Krasarang Wilds.', `QuestCompletionLog`) WHERE `ID` = 49540;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Kun-Lai Summit!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to the Messenger Grummle in Valley of the Four Winds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to assist Lorewalker Cho in Kun-Lai Summit.nnSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to the Messenger Grummle in Valley of the Four Winds.', `QuestCompletionLog`) WHERE `ID` = 49541;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Townlong Steppes!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Taran Zhu in Townlong Steppes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Taran Zhu in Townlong Steppes.nnThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.nnAssist them with their assault against the yaungol.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Taran Zhu in Townlong Steppes.', `QuestCompletionLog`) WHERE `ID` = 49542;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Dread Wastes!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Bowmistress Li on the Serpent\'s Spine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Bowmistress Li on the Serpent\'s Spine in the Vale of Eternal Blossoms.nnThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.nnYou can reach Bowmistress Li by securing a kite and flying to the Serpent\'s Spine.nnDestiny calls!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Bowmistress Li on the Serpent\'s Spine.', `QuestCompletionLog`) WHERE `ID` = 49543;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Frostfire Ridge!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Farseer Drek\'Thar in Frostfire Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Farseer Drek\'Thar in Frostfire Ridge.nnThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.nnWith Farseer Drek\'Thar\'s aid, we will be able to establish a strategic position in Draenor to fight against our enemies.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Farseer Drek\'Thar in Frostfire Ridge.', `QuestCompletionLog`) WHERE `ID` = 49545;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Gorgrond!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Durotan in Gorgrond.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Durotan in Gorgrond.nnDurotan is seeking allies to help us navigate the savage landscape of Gorgrond in hopes that we will find ancient powers to help us destroy the Iron Horde.nnSpeak with him and see what secrets the lands hold.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Durotan in Gorgrond.', `QuestCompletionLog`) WHERE `ID` = 49546;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Talador!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Foreman Grobash in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Foreman Grobash in Talador.nnThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.nnForeman Grobash is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Foreman Grobash in Talador.', `QuestCompletionLog`) WHERE `ID` = 49547;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Spires of Arak!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Azik in the Spires of Arak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Azik in Spires of Arak.nnThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.nnWe need to find out what is causing them to leave their homeland, and why their wings have withered.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Azik in the Spires of Arak.', `QuestCompletionLog`) WHERE `ID` = 49548;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Nagrand!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Stone Guard Brox in Nagrand on Draenor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied members of the Horde are hereby ordered to report to Stone Guard Brox in Nagrand on Draenor.nnThrall is establishing a Horde outpost and needs help to stop the Warsong clan.nnSpeak with Bron Skyhorn to fly to Nagrand and meet up with the supply caravan.nnFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Stone Guard Brox in Nagrand on Draenor.', `QuestCompletionLog`) WHERE `ID` = 49549;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Shadowmoon Valley!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Wing Commander Nuainn in Shadowmoon Valley on Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Wing Commander Nuainn in Shadowmoon Valley on Outland.nnThe Burning Legion are laying siege to Wildhammer Stronghold, endagering our people and threatening their lives.nnWe need to reinforce the stronghold and stop the Burning Legion\'s relentless assault!nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Wing Commander Nuainn in Shadowmoon Valley on Outland.', `QuestCompletionLog`) WHERE `ID` = 49550;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Howling Fjord!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Macalroy in Howling Fjord.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Macalroy in Howling Fjord.nnThe port town of Valgarde is located in the heart of the Howling Fjord, and it allows for the Alliance to have an advantageous position to strike at the Scourge.nnAssist the soldiers stationed there.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Macalroy in Howling Fjord.', `QuestCompletionLog`) WHERE `ID` = 49551;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Zul\'Drak!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Crusader Lord Lantinga in Zul\'Drak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Crusader Lord Lantinga in Zul\'Drak.nnThe Scourge is massacring the local population in Zul\'Drak and converting them over to be part of the Scourge army.nnAssist the Argent Crusade and the Ebon Blade in stopping this threat.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Crusader Lord Lantinga in Zul\'Drak.', `QuestCompletionLog`) WHERE `ID` = 49552;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Sholazar Basin!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest.nnHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.nnWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49553;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Storm Peaks!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Rin Duoctane in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest.nnThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.nnSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Rin Duoctane in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49554;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Icecrown!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest.nnThe Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.nnIt is time to make the Lich King pay for his crimes.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.', `QuestCompletionLog`) WHERE `ID` = 49555;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Jade Forest!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Grand Admiral Jes-Tereth in Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Stormwind Keep in Stormwind.nnGrand Admiral Jes-Tereth is assembling a team for a high priority mission.nnHead to Stormwind Keep immediately to be briefed.nnGlory to the Alliance!', `QuestDescription`) WHERE `ID` = 49556;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Valley of the Four Winds!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chen Stormstout in the Valley of the Four Winds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Chen Stormstout in the Valley of the Four Winds.nnThe adventuring spirit of the Stormstouts is something that the Alliance can learn from.nnTravel with the Stormstouts and discover what secrets Pandaria holds.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Chen Stormstout in the Valley of the Four Winds.', `QuestCompletionLog`) WHERE `ID` = 49557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Krasarang Wilds!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ken-Ken in Krasarang Wilds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Zhu\'s Watch in Krasarang Wilds.nnThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.nnSpeak with Ken-Ken at Zhu\'s Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Ken-Ken in Krasarang Wilds.', `QuestCompletionLog`) WHERE `ID` = 49558;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Kun-Lai Summit!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to the Messenger Grummle in Valley of the Four Winds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to assist Lorewalker Cho in Kun-Lai Summit.nnSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to the Messenger Grummle in Valley of the Four Winds.', `QuestCompletionLog`) WHERE `ID` = 49559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Townlong Steppes!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Taran Zhu in Townlong Steppes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Taran Zhu in Townlong Steppes.nnThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.nnAssist them with their assault against the yaungol.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Taran Zhu in Townlong Steppes.', `QuestCompletionLog`) WHERE `ID` = 49560;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Dread Wastes!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Bowmistress Li on the Serpent\'s Spine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Bowmistress Li on the Serpent\'s Spine in the Vale of Eternal Blossoms.nnThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.nnYou can reach Bowmistress Li by securing a kite and flying to the Serpent\'s Spine.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Bowmistress Li on the Serpent\'s Spine.', `QuestCompletionLog`) WHERE `ID` = 49561;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Shadowmoon Valley!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Prophet Velen in Shadowmoon Valley on Draenor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Prophet Velen in Shadowmoon Valley on Draenor.nnThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.nnWith Prophet Velen\'s blessing, we will be able to establish a strategic position in Draenor to fight against the enemies of Azeroth.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Prophet Velen in Shadowmoon Valley on Draenor.', `QuestCompletionLog`) WHERE `ID` = 49562;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Gorgrond!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Yrel in Gorgrond.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Yrel in Gorgrond.nnYrel and Maraad are requesting for a small expedition to be sent into the wilds of Gorgrond.nnWe hope to gain a better understanding of the land in hopes that it will show us how to exploit weaknesses in the Iron Horde.nnAssist them with their expedition.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Yrel in Gorgrond.', `QuestCompletionLog`) WHERE `ID` = 49564;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Talador!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Foreman Eksos in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.nnThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.nnForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Foreman Eksos in Talador.', `QuestCompletionLog`) WHERE `ID` = 49565;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Spires of Arak!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Azik in the Spires of Arak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Azik in Spires of Arak.nnThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.nnWe need to find out what is causing them to leave their homeland, and why their wings have withered.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Azik in the Spires of Arak.', `QuestCompletionLog`) WHERE `ID` = 49566;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Nagrand!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lieutenant Balfor in Nagrand on Draenor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor.nnYrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan.nnSecure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan.nnGlory to the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Lieutenant Balfor in Nagrand on Draenor.', `QuestCompletionLog`) WHERE `ID` = 49567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Silvermoon City', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lady Liadrin in Silvermoon City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path.nnRegent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon.nnCome, $n, let us travel to Silvermoon with Thalyssra.', `QuestDescription`) WHERE `ID` = 49613;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightborne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Ji Firepaw in Orgrimmar to hear the end of this tale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Warchief will be pleased with our success.nnThalyssra and her nightborne will prove strong allies, I am sure.', `QuestDescription`) WHERE `ID` = 49614;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Lightforged', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories.nnMost likely since it involves seeing our beautiful world from space!nnIt all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Captain Fareeya on the Vindicaar', `QuestCompletionLog`) WHERE `ID` = 49698;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Forces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Qy\'telek, Herald of Uul\'gyneth', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people\'s city!nnWe must fight together to rid this place of such filth.nnI believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, $n!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Herald of Uul\'gyneth', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Qy\'telek', `PortraitGiverName`) WHERE `ID` = 49756;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Alliance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ambassador Moorgard at the Stormwind Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us.nnAzeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance.nnGo to Stormwind. Seek the king\'s ambassador at the embassy, then set out to spread the Light\'s justice across the land.nnPheta thones gamera, $n.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Ambassador Moorgard at the Stormwind Embassy.', `QuestCompletionLog`) WHERE `ID` = 49772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ambassador Blackguard at the Orgrimmar Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A new age dawns upon Highmountain, $n.nnAfter centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde.nnTo show the strength we bring to our allies, brave tauren like you must heed the call of adventure.nnYou have been invited to Orgrimmar. Meet with the ambassador at the warchief\'s embassy, then begin your journey across Azeroth.nnEarthmother be with you, $n.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Ambassador Blackguard at the Orgrimmar Embassy.', `QuestCompletionLog`) WHERE `ID` = 49773;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heritage of the Lightforged', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Captain Fareeya aboard the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your service to the Alliance has been most impressive, $p. I could not have done better myself. Well, I could... but not by much.nnCome, meet with me at the Vindicaar. It is time that we reward your diligence.', `QuestDescription`) WHERE `ID` = 49782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heritage of Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Mayla Highmountain in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your sojourn through Azeroth has been long, $p. And through it all, you have brought honor to Highmountain.nnNow Thunder Totem calls you home. It is time we thank you for all that you have done for us.', `QuestDescription`) WHERE `ID` = 49783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heritage of the Nightborne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet First Arcanist Thalyssra at the Nighthold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are among the first shal\'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home.nnReturn to Suramar so that we may thank you for helping our people reclaim a place in this world.', `QuestDescription`) WHERE `ID` = 49784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ghostlands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Umbric\'s home in the Ghostlands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you familiar with how the Void elves joined the Alliance? nnIt began with Alleria Windrunner finding out about a blood elf named Umbric. nnHe and his followers were banished from Silvermoon City for researching void magic.nnAlleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them.nnIt all began when she opened up a portal to go into the Ghostlands...', `QuestDescription`) WHERE `ID` = 49787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Alliance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ambassador Moorgard at the Stormwind Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mastering the whispers requires constant focus and discipline. Your dedication inspires all who bear the name ren\'dorei--for we have become children of the Void.nnYou have learned many lessons here, but the time has come to venture beyond Telogrus Rift.nnGo to Stormwind, the heart of the Alliance. There, the king\'s ambassador will greet you and guide you along your journey.nnAzeroth must be defended. I can think of no one better suited to answer that call than you, $p.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Ambassador Moorgard at the Stormwind Embassy.', `QuestCompletionLog`) WHERE `ID` = 49788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Delas in Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Delas Moonfang at the Antonidas Memorial in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command.$B$BI implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Find Delas Moonfang at the Antonidas Memorial in Dalaran.', `QuestCompletionLog`) WHERE `ID` = 49812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Adventure Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Special Duty Assignments to select your next adventuring destination.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.nnWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?nnOr will you fly north, joining the battle against the Lich King in Northrend?nnThe choice is yours, adventurer.', `QuestDescription`) WHERE `ID` = 49813;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Burning Crusade: To Outland!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go through the Dark Portal in Blasted Lands.nnThe Thrallmar Mage in the Orgrimmar Portal Room can help you get there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.$b$bTravel to the Blasted Lands, and pass through the Dark Portal.', `QuestDescription`) WHERE `ID` = 49816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Northrend!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take a zeppelin to Northrend.$b$bYou can board the Howling Fjord zeppelin in Tirisfal Glades, or the Borean Tundra zeppelin in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lich King stirs in the north.$b$bAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.$b$bWe need you to stop them, $n.', `QuestDescription`) WHERE `ID` = 49817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wars on Two Fronts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Special Duty Assignments to select your next adventuring destination.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! You have been called upon once again to assist the Horde in matters of great import.nnWill you assist the Horde\'s efforts against Deathwing and the Twilight Hammer?nnOr will you fly south to Pandaria, claiming its resources before the Alliance does first?nnMake your choice and head into battle!', `QuestDescription`) WHERE `ID` = 49846;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cataclysm First Responder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Farseer Krogar in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.$b$bFarseer Krogar in Orgrimmar can tell you more about Mount Hyjal, Vashj\'ir, and other areas that Deathwing has targeted.', `QuestDescription`) WHERE `ID` = 49851;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Pandaria!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Grommash Hold in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are hereby ordered to present yourself at Grommash Hold immediately.$b$bWe have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.', `QuestDescription`) WHERE `ID` = 49852;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disaster at Mount Hyjal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our brothers in the Cenarion Circle report that Deathwing\'s minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!$B$BYou can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Transportation to Moonglade Secured', `AreaDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Emissary Windsong at Nighthaven in Moonglade.', `QuestCompletionLog`) WHERE `ID` = 49855;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Adventure Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Special Duty Assignments to select your next adventuring destination.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.nnWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?nnOr will you fly north, joining the battle against the Lich King in Northrend?nnThe choice is yours, adventurer.', `QuestDescription`) WHERE `ID` = 49860;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Burning Crusade: To Outland!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go through the Dark Portal in Blasted Lands.nnThe Honor Hold Mage in the Mage District can help you get there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.$b$bTravel to the Blasted Lands, and pass through the Dark Portal.', `QuestDescription`) WHERE `ID` = 49862;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wrath of the Lich King: To Northrend!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take a ship to Northrend.$b$bYou can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lich King stirs in the north.$b$bAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.$b$bWe need you to stop them, $n.', `QuestDescription`) WHERE `ID` = 49863;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wars on Two Fronts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Special Duty Assignments to select your next adventuring destination.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! You have been called upon once again to assist the Alliance in matters of great import.nnWill you assist the Alliance\'s efforts against Deathwing and the Twilight Hammer?nnOr will you fly south to Pandaria, claiming its resources before the Horde does first?nnMake your choice and head into battle!', `QuestDescription`) WHERE `ID` = 49864;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cataclysm: First Responder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Naraat the Earthspeaker in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.$b$bNaraat the Earthspeaker can tell you more about Mount Hyjal, Vashj\'ir, and other areas that Deathwing has targeted.', `QuestDescription`) WHERE `ID` = 49865;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mists of Pandaria: To Pandaria!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Rell Nightwind in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn.$b$bWe have received word of a conflict in the seas to the south, and we need the help of an experienced $c to assist in the investigation.', `QuestDescription`) WHERE `ID` = 49866;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heritage of the Void', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Alleria Windrunner at Telogrus Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Throughout your journeys across Azeroth, you have achieved mastery over the forces that constantly seek to control you.nnYou have become a formidable weapon of the Alliance, $p. Return to the void rift so that we may honor your accomplishment.', `QuestDescription`) WHERE `ID` = 49928;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call for Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Aysa Cloudsinger at the Stormwind Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance has been beset by dangers growing throughout all of Azeroth.nnThe only way we will keep our friends safe is if we seek out new allies.nnI have been tasked as an ambassador to help seek these allies. Come to our embassy in Stormwind, I could use your help.', `QuestDescription`) WHERE `ID` = 49929;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call for Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ji Firepaw at the Orgrimmar Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, champion! I have been appointed as the Horde\'s diplomatic ambassador to our allies far and wide. nnIt is my duty to seek out those of like mind and spirit, and speak to them about joining the Horde.nnAs a renowned hero of the Horde yourself, your aid would be most appreciated! Come see me at the embassy in Orgrimmar when you are able.', `QuestDescription`) WHERE `ID` = 49930;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ambassador Blackguard at the Orgrimmar Embassy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered.nnGo to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal\'dorei within it.nnShow the world who we are, $c. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.', `QuestDescription`) WHERE `ID` = 49933;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thalyssra\'s Estate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lady Liadrin at the Estate of the First Arcanist in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Would you like to hear how the nightborne came to join the Horde?nnWe earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion.nnLor\'themar Theron later asked them to join him in Quel\'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...', `QuestDescription`) WHERE `ID` = 49973;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gifts of the Fallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Mathias Shaw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Earlier today, King Wrynn addressed the citizens of Stormwind at Lion\'s Rest in a speech given to formally announce the end of the war.nnAfter the crowd departed, I met privately with the King and his advisors to discuss a mysterious substance that has been found in Silithus.nnThis glowing ore appears to be most powerful and the Horde has wasted no time in extracting it from the great wound.nnThe king has ordered me to fill you in on the details, in preparation for an important mission.', `QuestDescription`) WHERE `ID` = 49976;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Summons to Orgrimmar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Nathanos Blightcaller.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Warchief has requested that you return to Orgrimmar as soon as possible. There is an urgent matter that requires your attention.nnI will fill you in on the details as soon as you arrive.nnYou will find me near the entrance of Grommash Hold. The Dark Lady has plans for you, $n. I would not keep her waiting...', `QuestDescription`) WHERE `ID` = 49977;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Witness to the Wound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with the SI:7 commander in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve already sent operatives to Silithus to establish a base camp.nnTheir orders are to monitor the operations of the Horde and gather any information they can find on this mysterious substance.nnOne of my SI:7 commanders is currently awaiting your arrival. Go with speed.', `QuestDescription`) WHERE `ID` = 49981;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Witness to the Wound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Grol Warblade in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bilgewater Cartel have already begun mining operations in Silithus to extract this mysterious substance.nnThe Warchief has insisted that you personally oversee the extraction efforts in Silithus and prevent the Alliance from interfering.nnGallywix seemed less than pleased with your appointment, but nobody refuses Sylvanas...nnYou must go to Silithus at once. The base commander is awaiting your arrival.', `QuestDescription`) WHERE `ID` = 49982;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bret Test - SQL', `LogTitle`) WHERE `ID` = 50035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It\'s a Sabotage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant $1oa dynamite bundles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound.nnLuckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder.nnWhat unsophisticated machinery!nnTake these dynamite bundles and plant them on the inactive shredders around the mining camp.nnIt\'ll take those greedy goblins weeks to get back up and running again!', `QuestDescription`) WHERE `ID` = 50046;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Free Samples', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Mysterious Ore samples.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance.nnMy agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast.nnIn other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive.nnTake the ore samples to Khargus Stonemantle for analysis when you return.', `QuestDescription`) WHERE `ID` = 50047;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Seething Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Seething Shore battleground.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve received reports of an island off the coast of Silithus that is ripe with Azerite deposits.nnIt is vital that we secure the island before the Horde learns of its existence.nnMaster Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!', `QuestDescription`) WHERE `ID` = 50048;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker\'s Perspective', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Khadgar\'s letter to Magni Bronzebeard in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sargeras has left a scar upon our world, $n. A scar that will not soon heal...nnIt appears that the scars between the Alliance and Horde have yet to heal as well.nnToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.nnI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.nnThe letter contains information that may prove valuable to him.', `QuestDescription`) WHERE `ID` = 50049;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Spies Allowed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa SI:7 Operatives in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey $n, I\'m glad you\'re here.nnI\'m in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don\'t have a good feelin\' about this place!nnTo make matters worse, I\'ve been gettin\' reports of Alliance spies snoopin\' around the camp!nnLook kid, the Dark Lady has plans for this mysterious ore and I ain\'t going to be the one to dissapoint her, know what I mean?nnGet over to the mining camp and take out those SI:7 spies before they ruin the whole operation!', `QuestDescription`) WHERE `ID` = 50052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lazy Prospectors!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Motivate $1oa Lazy Prospectors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been around long enough to know you can never trust a goblin with an orc\'s work.nnGallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we\'re going to get anything done!nnI\'ve already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness!nnGet out there and put those lazy prospectors in their place!', `QuestDescription`) WHERE `ID` = 50053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Seething Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Seething Shore battleground.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve received reports of an island off the coast of Silithus that is ripe with Azerite deposits.nnIt is vital that we secure the island before the Alliance learns of its existence.nnNathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!', `QuestDescription`) WHERE `ID` = 50054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker\'s Perspective', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Khadgar\'s letter to Magni Bronzebeard in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sargeras has left a scar upon our world, $n. A scar that will not soon heal...nnIt appears that the scars between the Alliance and Horde have yet to heal as well.nnToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.nnI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.nnThe letter contains information that may prove valuable to him.', `QuestDescription`) WHERE `ID` = 50055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni Bronzebeard at the Wound in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I been travelin\' the land, seekin\' out anyone who might know how ta heal Azeroth. I\'ve consulted ancient sages, druids, shamans... from dragons ta titan keepers. Nobody\'s seen anythin\' like this before.nnWent ta Karazhan ta speak with Khadgar. Studyin\' those old tomes o\' his, we came up with an idea. No tellin\' if it\'s gonna work, but we gotta try.nnCome ta Silithus. Meet me at the wound. Time is runnin\' out fer Azeroth, $p.', `QuestDescription`) WHERE `ID` = 50056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power in Our Hands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Sword in Silithus and draw its power into your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That sword of Sargeras is surgin\' with dark energies. They\'re seepin\' into Azeroth\'s heart like poison.nnThe blade\'s power must be snuffed out.nnThe Pillars o\' Creation could do it, but they\'re keepin\' the tomb sealed. So we need other vessels capable o\' harnessin\' vast energies.nnVessels like those artifact weapons you and the other champions wield.nnIt\'s a risk, $p. We don\'t know what Sargeras\' power will do ta those weapons. But unless we act now, the heart of Azeroth is sure ta die.', `QuestDescription`) WHERE `ID` = 50057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Light!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Stormwind and speak with Aysa Cloudsinger to hear the end of his tale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lightforged Draenei will be happy to join the Alliance.nnOur cause is now yours, $n.nnLet us return to Stormwind. Captain Fareeya will speak with our people.', `QuestDescription`) WHERE `ID` = 50071;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Friendly Gesture', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach Friendly with Sporeggar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Life in the marsh has not been easy, $n. We want to live in harmony with those that call it home, but our enemies out here threaten our existence.nnWork with us. Help the people of Sporeggar thrive.', `QuestDescription`) WHERE `ID` = 50130;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Outside Perspective', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach Neutral with Sporeggar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thank you for everything you have done for my people, but they are still scared of outsiders.nnFight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!', `QuestDescription`) WHERE `ID` = 50131;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Source of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Silithid Brains.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground.nnThese new silithid seem stronger than before!nnMy hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras.nnI\'ve been tasked with studying the effects that this mysterious power is having on the silithid hives.nnBring me as many intact silithid brains as you can carry and I\'ll begin the research!', `QuestDescription`) WHERE `ID` = 50226;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Larvae By The Dozen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Silithid Broodlings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'How did the silithid survive the blade of Sargeras? I\'m perplexed!nnI\'ve never encountered a species that can adapt to changes in the environment as quickly as the silithid can.nnThe larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive.nnIs it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play?nnScience must find the answer!', `QuestDescription`) WHERE `ID` = 50227;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Twilight Survivor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Michiel Voidstrider\'s head.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Silithus used to be overrun with members of the Twilight\'s Hammer.nnThe cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak.nnMost of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.nnWe cannot let Michiel rally the remaining survivors to action. He must be stopped!', `QuestDescription`) WHERE `ID` = 50228;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Wee Bit O\' Cloth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa scraps of Twilight Silk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, is that you I hear rustlin\' about out there? It\'s me, Angus Stormbrew!nnThere are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk!nnThis is the only outhouse in all o\' Silithus! Trust me I spent hours lookin\' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I\'ve got a uhh problem...nnThere\'s no cloth to... you know...nnSee if ye can find me a wee bit o\' cloth and sneak it in through the door!', `QuestDescription`) WHERE `ID` = 50229;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Source of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Silithid Brains.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The silithid are all riled up and stronger than ever!nnMy guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras!nnI\'ve been ordered to study the effects that this mysterious power is having on the sillithid.nnBring me as many intact silithid brains as you can carry and I\'ll begin the research!', `QuestDescription`) WHERE `ID` = 50230;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Larvae By The Dozen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Silithid Broodlings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'How did the silithid survive the blade of Sargeras?!nnI\'ve never encountered a species that can adapt to changes in the environment as quickly as the silithid!nnThere\'s gotta be a way to tame these suckers! Harness their evolutionary biology for our profit!nnWe gotta start training \'em young! Forget about the old crusty adults, we need babies!nnSteal me as many of the silithid larvae as you can carry, and I\'ll find a way to train \'em!', `QuestDescription`) WHERE `ID` = 50231;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Twilight Survivor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Michiel Voidstrider\'s head.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This land was once overrun with members of the Twilight\'s Hammer.nnThe cult was presumed to be exterminated, but darkness always survives in the shadows.nnMost of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.nnWe cannot let this fanatic rally the remaining survivors to action! Bring me his head!', `QuestDescription`) WHERE `ID` = 50232;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Choice of Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn more about potential allies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance.nnI\'ve made some notes about some potential allies that may be willing to join the Alliance.nnLearn more about them, then speak with me.', `QuestDescription`) WHERE `ID` = 50239;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Choice of Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn more about potential allies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As ambassador, it is my duty to bolster the Horde\'s ranks and strengthen our numbers in the face of danger.nnYour adventures have led you to many different people who can aid the Horde if we can convince them to join our cause.nnI\'ve kept a record of the most promising potential allies. The choice of which to approach first is yours.', `QuestDescription`) WHERE `ID` = 50242;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mail Must Flow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help the Postmaster sort at least 15 letters within the time limit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Due to all of the recent shenanigans, I\'m running short on mailementals to sort letters.nnIt\'s a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond.nnI like to make a little game out of it. How many can you sort in one minute?', `QuestDescription`) WHERE `ID` = 50247;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Second Ally For the Cause', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second ally to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have taken an important first step in strengthening the Alliance, $n. Well done.nnBut I fear a single new ally will not deter the Horde. The warchief will not rest until Orgrimmar\'s forces vastly outnumber the defenders of Stormwind.nnI must ask that you work to secure our next ally. We cannot afford any delay.', `QuestDescription`) WHERE `ID` = 50248;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Second Ally For the Cause', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second ally to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One new ally will prove useful. A second will make us even stronger.nnEven now, the Alliance plots and schemes against us. We must move quickly, or they will strike before we are prepared to counter their aggression.nnSay the word when you are ready to begin pursuit of our next ally. There must be no hesitation.', `QuestDescription`) WHERE `ID` = 50254;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni Bronzebeard at the Wound in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I been travelin\' the land, seekin\' out anyone who might know how ta heal Azeroth. I\'ve consulted ancient sages, druids, shamans... from dragons ta titan keepers. Nobody\'s seen anythin\' like this before.nnWent ta Karazhan ta speak with Khadgar. Studyin\' those old tomes o\' his, we came up with an idea. No tellin\' if it\'s gonna work, but we gotta try.nnCome ta Silithus. Meet me at the wound. Time is runnin\' out fer Azeroth, $p.', `QuestDescription`) WHERE `ID` = 50300;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stranger in a Strange Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Chromie in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hi. I\'m Ambassador Blackguard.nnI am honored to welcome you to Orgrimmar, $r.nn<He smiles unconvincingly.>nnAs a lifetime of adventure unfolds before you, be assured that... uh...nnYou know what? I\'ve been saying this same greeting all day. Enough\'s enough.nnTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.', `QuestDescription`) WHERE `ID` = 50303;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stranger in a Strange Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Chromie in Stormwind City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to Stormwind, $r. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! nnAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!nnAfter that, an emissary of the ren\'dorei is waiting to welcome you to the city. Sounds like a busy day for you!nnHave a pleasant stay, $n!', `QuestDescription`) WHERE `ID` = 50305;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stranger in a Strange Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Chromie in Stormwind City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to Stormwind, $r. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! nnAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!nnAfter that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you!nnHave a pleasant stay, $n!', `QuestDescription`) WHERE `ID` = 50313;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disturbance Detected: Ulduar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Relive the expedition to Ulduar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'re late. Don\'t you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar? You were late then too. You should really try to be more punctual.nnWell, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We\'ve got times and places to be.nn<Vormu gestures impatiently for you to leave.>', `QuestDescription`) WHERE `ID` = 50316;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Timely Summons from Northrend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Vormu in Dalaran above Crystalsong Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran, and lend her your aid.nnNo, not this Dalaran, the other one. Yes I know, it\'s terribly confusing.', `QuestDescription`) WHERE `ID` = 50318;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stranger in a Strange Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Chromie.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hi. I\'m Ambassador Blackguard.nnI am honored to welcome you to Orgrimmar, $r.nn<He smiles unconvincingly.>nnAs a lifetime of adventure unfolds before you, be assured that... uh...nnYou know what? I\'ve been saying this same greeting all day. Enough\'s enough.nnTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.', `QuestDescription`) WHERE `ID` = 50319;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grant Me Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Randolph Moloch, Lord Overheat, and Hogger.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t care who you pledge allegiance to, $r. I need Hogger dead!nnHe--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.', `QuestDescription`) WHERE `ID` = 50335;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The G-Team', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mekgineer Thermaplugg.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'d keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.nnLet\'s get you to work! Go down into this tunnel until you get to Tinkers\' Court. Hopefully you\'ll know what to do when you meet Mekgineer Thermaplugg.nnOur leader, Commando Hann Ibal waits somewhere in there. He\'ll reward you handsomely for all your work.nnProbably....', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Watch out for his bombs!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mekgineer Thermaplugg', `PortraitGiverName`) WHERE `ID` = 50336;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The G-Team', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill the Electrocutioner 6000.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That Murd Doc is crazy, $c. Never, ever, let you find yourself in an aircraft with that gnome.nnStealth usually isn\'t my thing, and it\'s certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.nnThe Electrocutioner is in charge of the aircraft...nn...and I hate aircraft. I\'m not getting in any sort of aircraft!nnUse this parachute to drop down afterwards and speak with Commando Face for your next job.', `QuestDescription`) WHERE `ID` = 50337;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The G-Team', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill the Viscous Fallout.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'How did you get in here, $n?nnI\'m Murd Doc of the G-Team and we could use the help of a $r like you.nnHelp us defeat the irradiated inhabatants that now call Gnomeregan home, and I\'ll make you an honorary G-Team Commando!nnTake this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout. After you\'re done, report to Commando B.E Barechus by the west hallway. You two will get along great, I\'m sure.', `QuestDescription`) WHERE `ID` = 50338;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Recent Discovery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Nathanos Blightcaller.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Earlier today, the leaders of the Horde gathered together for a feast in celebration of our victory over the Burning Legion.nnAs the others were feasting, Gallywix requested a private audience with the Dark Lady.nnIt seems that he has found a mysterious substance in Silithus... a magical ore unlike any we have ever encountered before. nnThe warchief has ordered me to fill you in on the details, in preparation for a special assignment.', `QuestDescription`) WHERE `ID` = 50341;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desert Research', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Pixni Rustbomb.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The dark blade of Sargeras has cast a shadow of destruction over this land.nnIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.nnIf it were up to me, I\'d burn those wretched hives once and for all! However, it is not up to me.nnThe Dark Lady wants the surviving silithid dissected and studied. nnPixni Rustbomb is conducting the research and is in need of a "collector."', `QuestDescription`) WHERE `ID` = 50358;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khadgar\'s Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, $n.nnHurry and see what it is that he wants. I want him gone as soon as possible.nnThe last thing we need is a human nosing around in Horde business!', `QuestDescription`) WHERE `ID` = 50360;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Blood of Azeroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Magni Bronzebeard\'s message.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do the leaders of the Alliance and Horde even know what they\'re fightin\' over?nnThis substance that is risin\' up from the wound is the lifeblood of Azeroth!nnWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we\'ve got. We cannot allow her ta die!nnI trust ye, $n, and I know that yer voice carries great weight among the Horde. Ye must reason with \'em ta stop this madness!nn\'Tis the only hope our world has...', `QuestDescription`) WHERE `ID` = 50364;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Summons to Stormwind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Mathias Shaw in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'King Wrynn has requested that you return to Stormwind as soon as possible. There is an urgent matter that requires your attention.nnI will fill you in on the details as soon as you arrive.nnYou will find me at Lion\'s Rest. Be swift... our window of opportunity may already be closing!', `QuestDescription`) WHERE `ID` = 50371;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desert Research', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Tammy Tinkspinner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The dark blade of Sargeras has cast a shadow of destruction over this land.nnIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.nnWe need to find out how the silithid avoided destruction and what effect the blade is having on their hives.nnThe crown wants the surviving silithid dissected and studied. nnTammy Tinkspinner is conducting the research and is in need of a "collector."', `QuestDescription`) WHERE `ID` = 50372;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Recent Arrival', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The situation in Silithus appears to be gaining more attention.nnArchmage Khadgar just arrived while you were away. It seems that he is here to speak with you, $n.nnIt appears urgent. I would speak with him as soon as possible.', `QuestDescription`) WHERE `ID` = 50373;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Blood of Azeroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Magni Bronzebeard\'s message.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do the leaders of the Alliance and Horde even know what they\'re fightin\' over?nnThis substance that is risin\' up from the wound is the lifeblood of Azeroth!nnWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we\'ve got. We cannot allow her ta die!nnI trust ye, $n, and I know that yer voice carries great weight among the Alliance. Ye must reason with \'em ta stop this madness!nn\'Tis the only hope our world has...', `QuestDescription`) WHERE `ID` = 50374;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Titanic Innovation', `LogTitle`) WHERE `ID` = 50432;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Valiant Effort', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue $1oa Wounded Valiants from the training grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.nnWhile we managed to escort many to safety, there are some who were wounded in the chaos.nnSearch the training grounds for any survivors from the onslaught.nnWe need all the help we can get.', `QuestDescription`) WHERE `ID` = 60003;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue $1oa Wounded Valiants from the training grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale.nnWhile we managed to escort many to safety, there are some who were wounded in the chaos.nnSearch the training grounds for any survivors from the onslaught.nnWe need all the help we can get.', `QuestDescription`) WHERE `ID` = 60004;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Thanikos at Xandria\'s Vigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Temple of Courage must not fall!nnAll kyrian learn to fight in its hallowed halls. Not only to protect Bastion, but to ensure their own safety when retrieving souls from across the veil. nnTravel there at once. Seek out Thanikos, the Paragon of Courage\'s loyal hand.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Seek out Thanikos at Xandria\'s Vigil.', `QuestCompletionLog`) WHERE `ID` = 60005;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reclaim Xandria\'s Vigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In a fair fight our warriors could stand against countless swarms of these Maldraxxi.nnThis was no fair fight, outsider.nnThey came without warning. Without cause. We were caught unprepared.nnThey must not be allowed to encroach any further. This stops here.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Thanikos in Xandria\'s Vigil.', `QuestCompletionLog`) WHERE `ID` = 60006;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the Anima Conflux, Eternity Plating, and Archonic Resonator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can rebuild this colossus\'s core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise.nnReplacements are in order!nnI require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom!nnI\'ll take care of the rest. Quickly, now!', `QuestDescription`) WHERE `ID` = 60007;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay House of Constructs forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will show these Maldraxxi insurgents the price for their betrayal.nnThe northern grounds have been taken by the House of Constructs, home to Maldraxxus\' most resilient warriors.nnThey have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.', `QuestDescription`) WHERE `ID` = 60008;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '<As you give the medallion to A\'dal, it disappears into his being in a flash of light.>$B$B<You are briefly shown a glimpse of a moment... perhaps in the future.  You see Akama and Maiev coming out of the Warden\'s Cage, fighting their way to the Dark Temple.  A third figure shrouded in shadows is aiding them.  Upon closer inspection you notice that the figure is you.>', `RewardText`) WHERE `ID` = 11052;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Will you lay the candle down and call the Headless Horseman from his doomed rest?', `RewardText`) WHERE `ID` = 11405;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Felo\'melorn... I can barely believe that such great power is locked within a blade as beautiful as this!$b$bWith this weapon in your hands, the Legion will surely fall!', `RewardText`) WHERE `ID` = 11997;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'With Sartharion slain, surely Deathwing and Sinestra\'s plans are now stalled.', `RewardText`) WHERE `ID` = 24579;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Ah, Varzok. Yes, I know him well. He be makin\' no mistake in sendin\' you here.', `RewardText`) WHERE `ID` = 31812;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You fight with the determination of one who does not fear defeat, but does not tolerate it, either. You will go far.', `RewardText`) WHERE `ID` = 31813;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You do not understand. I have not been defeated, merely set back.', `RewardText`) WHERE `ID` = 31814;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you, outsider! Thank you very much.$b$BYou have done more for me than my own people ever have.$b$bLady Challiane would never take the word of a lowly cellarman over her vintners.$b$bNow I can use this recipe to earn her favor, and then the favor of our beloved queen Azshara...', `RewardText`) WHERE `ID` = 38203;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thaon will be dearly missed. We may not have always seen eye to eye, but he was a great druid and a true protector of the vale.$b$bXavius will pay for his death...', `RewardText`) WHERE `ID` = 38323;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I am impressed that you were able to defeat such a powerful demon. We are fortunate that you have lent us your aid.', `RewardText`) WHERE `ID` = 38656;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thanks to you, the great eagles of Highmountain will live on.$b$bOne of the eggs I thought was too damaged to salvage appears to be hatching...', `RewardText`) WHERE `ID` = 39305;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent. You\'ve absorbed that fel lord\'s power and become more powerful in-turn.nnNow, we can fully concentrate on destroying the Legion and their Brood Queen.', `RewardText`) WHERE `ID` = 39495;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Those worm guts will be perfect for a special sort of rope.', `RewardText`) WHERE `ID` = 40069;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'These eggs are in poor condition, $n. Some are cracked and spoiled, while others are cold to the touch.$b$bYet there is still hope. I believe a few of the eggs you recovered can be saved.', `RewardText`) WHERE `ID` = 40070;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Korgrul deserved his fate. Thank you, $n.', `RewardText`) WHERE `ID` = 40071;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '$n, I\'m glad you came.$b$bI\'ve found information on just the thing we need to turn this war in our favor.', `RewardText`) WHERE `ID` = 40267;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Our next journey will be to Icecrown, $n.$b$bThere, in the heart of the Scourge, we will find Felo\'melorn.', `RewardText`) WHERE `ID` = 40270;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '$n, I\'m pleased you came on such short notice.$b$bWe have a great undertaking here in the Moonglade that is about to begin, one in which you will play a key role.', `RewardText`) WHERE `ID` = 40643;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well done, $n!$b$bNow that the path is open we can begin our journey to Val\'sharah.', `RewardText`) WHERE `ID` = 40644;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You did well to navigate through the Emerald Dream to get to this place. Still, there are times when you might wish to return here a bit more quickly. This spell will guide you.$b$bTraveling the Dreamway is no small feat in itself, but it pales to the tasks ahead.', `RewardText`) WHERE `ID` = 40645;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent choice, $n!$b$bWith the power of that weapon in your hands we will be able to bring balance back to Azeroth.', `RewardText`) WHERE `ID` = 40646;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I owe you my life, $n. If it wasn\'t for your actions I\'d be dead or worse.$b$bThat traitor, Xavius, may have taken Ursoc but at least we were able to recover the claws. Hope is not lost to us yet.', `RewardText`) WHERE `ID` = 40647;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Good, soon the ritual will be ready to begin.', `RewardText`) WHERE `ID` = 41106;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You could say you\'ve got my attention, pal!$B$BSo you\'re looking to hire me on full-time, eh? Well if the future payoffs are anything like this, I\'d say you\'ve got yourself a deal.', `RewardText`) WHERE `ID` = 41112;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I understand he may be unconventional, but I think this goblin is exactly what we\'ll need to quickly get this new Tirisgarde up to snuff for the task at hand.$B$BI\'ve already sent word to many talented mages who can help. They await transportation to the Hall, where they can begin their new purpose.$B$BShall we?', `RewardText`) WHERE `ID` = 41113;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You learn quickly, $n. $B$BI think Kathra\'natir will rue the day he made you his enemy.', `RewardText`) WHERE `ID` = 41114;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Oh, thank the Magistrix! I was worried it was lost forever.$b$bI see that this ring has seen some... use. I do hope it doesn\'t belong to anyone important. Or... vocal.', `RewardText`) WHERE `ID` = 41123;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'So you\'re a Conjuror now, huh? Fan-cy!$B$BWe\'ve got a good start with this Tirisgarde thing here, but I think we should keep up the recruiting if we actually plan on invading demon-town.$B$BFortunately for you, nobody negotiates contracts like a goblin!', `RewardText`) WHERE `ID` = 41124;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Alright, then! I can get started recruiting, and you can get to taking the fight to the demons!$B$BYeah, I know I\'m letting you take the easy job, but hey, what are friends for?', `RewardText`) WHERE `ID` = 41141;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Lespin shall pay for his crimes!', `RewardText`) WHERE `ID` = 41146;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent. I shall have these melted down and turned into ingots for my next batch of commissions.', `RewardText`) WHERE `ID` = 41307;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Those wretched creatures are a scourge on our beautiful lands. At least they had good taste in their accessories.$b$bOr maybe they just like shiny things.', `RewardText`) WHERE `ID` = 41320;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'By the Magistrix, I had forgotten how ugly that thing is. Impeccable workmanship, obviously. Just... ugh. I should melt the whole thing down.', `RewardText`) WHERE `ID` = 41466;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The Claws of Ursoc?$b$bI thought I\'d go the rest of my days without hearing of them again. Is our situation truly so dire? They were sealed away for good reason!', `RewardText`) WHERE `ID` = 41468;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent! We will need this water to enter the Emerald Dream. I\'ve prepared offerings for Ursol, brother of Ursoc. We will need his help to bypass the magical wards placed upon the claws.nnGive me a moment... and let us hope Ursol will aid us.', `RewardText`) WHERE `ID` = 41782;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You are powerful indeed, but strength alone will not impress me.', `RewardText`) WHERE `ID` = 41790;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well done, $n. You handled yourself with honor!$b$bYou\'ve done well so far, yet a single trial remains before I will give you my blessing.', `RewardText`) WHERE `ID` = 41791;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You have passed every trial I\'ve placed before you and emerged victorious. You are worthy indeed of my brother\'s legacy, and have earned my blessing!$b$bGo, seek out the claws and claim them as your own.', `RewardText`) WHERE `ID` = 41792;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'So, Xavius is behind this. A thousand deaths isn\'t enough of a punishment for that defiler!$b$bBut, you have returned with the claws, that is not an accomplishment that even I could have performed.$b$bYou are truly the hero we need to face the Legion.', `RewardText`) WHERE `ID` = 41918;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I can\'t believe it! I hoped it would work, but I couldn\'t be sure.nnYou recovered heirlooms passed down by my family for many generations.nnI thought them lost forever.', `RewardText`) WHERE `ID` = 42425;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I wish it did not have to come to this, truly.', `RewardText`) WHERE `ID` = 42747;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The owlbeasts are... melting the dryads down and using their bones to create minions?! How... how could this even be?', `RewardText`) WHERE `ID` = 42748;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I don\'t know if grell have mothers, but I hope that one never kissed his mother with his mouth.', `RewardText`) WHERE `ID` = 42865;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you, $n. You are welcome in our village anytime.', `RewardText`) WHERE `ID` = 42883;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The grell trapped our young within the huts. They are no longer at risk, thanks to your generous efforts.', `RewardText`) WHERE `ID` = 42884;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I am not hungry any more. I can think- I will live! Oh, Arluin...', `RewardText`) WHERE `ID` = 43569;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The spell has begun. Return to me when it is complete. Fate is in the hands of time now.', `RewardText`) WHERE `ID` = 44208;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Ah, $n, it\'s good to see you on your feet! The members of the Council of Six are recuperating from their ordeal.$b$bThe intensity of the teleportation spell can be disorienting. It seems you lost consciousness for a time, but at least you didn\'t awaken to find yourself stuck in a wall!$b$bDalaran has been relocated to the Broken Isles. From here, we will spearhead the effort to acquire the Pillars of Creation and drive the Legion from Azeroth once and for all!', `RewardText`) WHERE `ID` = 44663;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'A fitting end.', `RewardText`) WHERE `ID` = 45417;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'With the Eye of Aman\'Thul in our possession, we are one step closer to sealing the portal.', `RewardText`) WHERE `ID` = 45420;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I have spent a lifetime hunting the wicked and making them pay for their crimes. When I strike a demon down, I feel a measure of justice has been served.$b$bYou have been an instrument of retribution this day, $ct. Had you walked a different path, you might have made a worthy Warden.', `RewardText`) WHERE `ID` = 46246;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'We must take every opportunity to shatter the will of Kil\'jaeden\'s army.$b$bWhen they see their mightiest champions crumble to dust, they will realize that the vaunted Legion is doomed to fall.', `RewardText`) WHERE `ID` = 46250;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thinning the ranks of demons in locations like Faronaar and Felsoul Hold cuts the legs out from under the Legion.$b$bKil\'jaeden will fall!', `RewardText`) WHERE `ID` = 46252;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The Pillars of Creation are in place. The Tomb of Sargeras is sealed, and Aegwynn\'s echo is at rest.$b$b<Khadgar gestures toward the sky.>$b$bUnfortunately, we do not have that luxury.$b$bThough you won a great victory this day, there is no time for revelry. The final battle awaits us. Make ready.', `RewardText`) WHERE `ID` = 46253;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'When we faced the Deceiver, millennia of rage flooded my heart. Hatred took hold, blinding me to every thought but revenge.nnThankfully the Light helped me see that the future must not be defined by vengeance, but by hope. Your courage showed me that as well, $n.nnIn those last moments of Kil\'jaeden\'s life, I had to let go of the past. Not only for my own sake, but for the memory of my son.nnMy spirit and mind are clear and focused. Now we take the fight to Sargeras himself. Now we end the Legion.', `RewardText`) WHERE `ID` = 46805;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you for coming. I have something I\'d like to show you.', `RewardText`) WHERE `ID` = 47035;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You are a true hero, $n. Even though the demons freed Raalgar and thought him immortal, he was no match for you! Perhaps the Fel Heart will be of use to you. It is now available in the Matrix Core.', `RewardText`) WHERE `ID` = 47182;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Soon, the krokul will raid Nath\'raxas Hold. My people are anxious to begin.', `RewardText`) WHERE `ID` = 48442;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'We were a great civilization, once. But, now?... Thank you, $n. Our combined forces freed many from Nath\'raxas. With fewer slaves, and the Army of the Light on their doorstep, the Legion\'s influence over this region will be greatly diminished.', `RewardText`) WHERE `ID` = 48443;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Your champions discovered someone living in a cave beneath Oranaar. He is hiding from the Void-Touched, and he appears lucid.', `RewardText`) WHERE `ID` = 48445;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The voidcallers roaming the Shadowguard Incursion must be extinguished. Your people are sufficiently armed for the coming encounter.', `RewardText`) WHERE `ID` = 48446;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'With L\'ura defeated, and the voidcallers eliminated, the Shadowguard\'s dominance over the city has been crippled. if our campaign against the Legion is successful, there could be a future for the creatures living here.', `RewardText`) WHERE `ID` = 48447;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Three Legion facilities decimated in a single operation. Extraordinary.', `RewardText`) WHERE `ID` = 48448;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'One step closer to defeating the Legion.', `RewardText`) WHERE `ID` = 48600;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'There\'s nothing more beautiful than a lightburst charge erupting in a Legion stronghold. Your people afforded themselves well.', `RewardText`) WHERE `ID` = 48601;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Another lightforged to fight alongside your forces.', `RewardText`) WHERE `ID` = 48636;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I told the others; I will not abandon my people. I must remain here, but maybe you can help? I have discovered a way to purge the shadow from the void-addled.', `RewardText`) WHERE `ID` = 48654;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'What say you, offworlder?', `RewardText`) WHERE `ID` = 48910;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Another soul freed from the cruelty of the void.', `RewardText`) WHERE `ID` = 48911;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'A lightforged soldier can wade through a sea of demons. They will serve you well.', `RewardText`) WHERE `ID` = 48912;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is finished. At long last, the Burning Crusade is over.$b$bI thank you for all you did, $n. With the power of Argus feeding his Dark Pantheon, Sargeras would have been unstoppable.$b$bOn behalf of the draenei, the eredar, the countless worlds destroyed by the Legion...$b$bThank you.', `RewardText`) WHERE `ID` = 49015;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Do not delay, $n. The Winterhoof Well\'s taint must be removed!', `CompletionText`) WHERE `ID` = 754;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Have you been to the Forgotten Pools, $n? Did you find anything?', `CompletionText`) WHERE `ID` = 870;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'My sister likes to wander, but she\'s been gone for a long time now...', `CompletionText`) WHERE `ID` = 945;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Practice!', `CompletionText`) WHERE `ID` = 2460;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'When you have faced the challenge that lies before you, your understanding of strenght of body and strenght of heart will be fully realized.  Until that time, I cannot help you further.', `CompletionText`) WHERE `ID` = 6001;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized. Until that time, I cannot help you further.', `CompletionText`) WHERE `ID` = 6002;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.$B$BYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!$B$BSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!', `CompletionText`) WHERE `ID` = 7002;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.$B$BWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.$B$BYou must strike at our enemy\'s base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!', `CompletionText`) WHERE `ID` = 7026;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', '<Warmaster Laggrond salutes you.>$B$BIt is your time, $N. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.$B$BWell done! Present your initiate\'s insignia.', `CompletionText`) WHERE `ID` = 7163;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'It is good to see you again, $C. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.$B$BYour time has come again, $N. You have earned a new ranking and as such, a new insignia denoting this rise in stature.$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7164;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7165;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Your radiate command and power, $C. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.$B$BRise, Hero of Frostwolf. Rise and be honored!$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7166;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Drek\'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.$B$BYou have earned the Eye of Command.$B$BPresent your insignia, Commander $N.', `CompletionText`) WHERE `ID` = 7167;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, $c. The time has come.$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7168;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7169;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'I must know, $n. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!$B$BYou have earned reverence among the Guard. Present your insignia!', `CompletionText`) WHERE `ID` = 7170;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Before me stands an exalted hero of the Alliance.$B$B<Lieutenant Haggerdin salutes.>$B$BFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!$B$BPresent your insignia.', `CompletionText`) WHERE `ID` = 7171;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Let them hear your voice, Commander $N! Let them know fear. Show them what power the Stormpike holds in their rank!', `CompletionText`) WHERE `ID` = 7172;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, $n.', `CompletionText`) WHERE `ID` = 7385;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf\'s storm crystals.$B$BThe Circle accepts such offerings, $n.', `CompletionText`) WHERE `ID` = 7386;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', '<Vartrus groans.>', `CompletionText`) WHERE `ID` = 7632;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8496;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8497;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8540;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8541;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Yup, I be glad you\'re here, mon. You helped me before, and now I need your help again. We still lookin\' ta bring in more mithril bars for the war effort; gonna build lots of armor and weapons and things to go squish them bugs at Ahn\'Qiraj.$B$BSo if you be a true friend, you bring me back more stacks of mithril bars. I take all you got until we hit our quota. You have some for me now?', `CompletionText`) WHERE `ID` = 8546;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'In fact it does appear that we are in need of even more purple lotus, $c. While my own studies have yet to determine a new useful application for the herb, there are tried and true methodologies yet to be employed.$B$BI need you to once again go out into the field and collect at least twenty purple lotus samples. Return them to me here.', `CompletionText`) WHERE `ID` = 8583;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'It\'s true, $c, I still need more heavy leather. The requests from the generals and their quartermasters seem endless. And that\'s nothing compared to what the zeppelin masters are asking for!$B$BI need to get my quota collected on the double. $n, bring me more stacks of heavy leather as soon as you can!', `CompletionText`) WHERE `ID` = 8589;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', '$c, as you can see I still need to gather up more thick leather. Once again I ask your help with this task, and promise that if you complete it, you will be recognized for your efforts.$B$BTime is of the essence! Return to me with the thick leather so that we can finish our preparations and go to war, hero!', `CompletionText`) WHERE `ID` = 8591;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', '$BThe "Holly Preserver" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.$B$BThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.', `CompletionText`) WHERE `ID` = 8763;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8779;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8780;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You have something for me, $n?', `CompletionText`) WHERE `ID` = 8782;
