-- English that upstream kept in its frFR rows (no translation made: the frFR row held the English text) and that
-- the frFR clean-up removed: it goes into fields still empty here. Mangled line breaks ("...nnWhen") become $B$B.
-- The few lines that really were French are translated by hand.
UPDATE `quest_template` SET `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to the assistant.', `QuestCompletionLog`) WHERE `ID` = 35172;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED]Down to Azsuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar to fly down to Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we must find a way to reseal the Tomb of Sargeras.$B$BWhen I was in the Chamber of the Guardian below, I unearthed a tome that spoke of an ancient relic that might be the key to stopping the Legion.$B$BOur search begins here on the ancient elven island of Azsuna. Long ago, it was where the elves of Suramar perfected their mightiest of magics. Now it is a cursed ruins.$B$BI know that the demon hunters of the Illidari have established a camp on the island. Ready to take wing?', `QuestDescription`) WHERE `ID` = 36810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood of the Annihilan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Malinoth\'s Blood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must make contact with Lord Illidan\'s spirit. But to do that, we need something powerful enough to fuel the nether crucible. I know just the thing.$B$BA pit lord named Malinoth has taken over a nearby cave. If we acquire his blood, you can use it to power the crucible. Then, you can make contact with Illidan in the Twisting Nether.', `QuestDescription`) WHERE `ID` = 36939;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Twisting in the Nether', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Malinoth\'s Blood with the Nether Crucible to cast yourself into the Twisting Nether.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Quickly, $n. Pour the pit lord\'s blood into the crucible and make contact with Illidan\'s spirit.$B$BFind out everything you can. If we\'re to defeat the Legion, we must rescue Lord Illidan.', `QuestDescription`) WHERE `ID` = 36949;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Forest God\'s Proposal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Prince Farondis\' memory from the past.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I remember now. I was walking through my gardens, when I was visited by...$b$b<Farondis pauses.>$b$b...actually, it\'s easier if I show you, rather than explaining the whole thing.', `QuestDescription`) WHERE `ID` = 37258;
UPDATE `quest_template` SET `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Challenger Savina at Stormshield in Ashran.', `QuestCompletionLog`) WHERE `ID` = 37271;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Academy Vault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the eastern wing of the Nar\'thalas Academy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The Tidestone of Golganneth must be contained within the Academy\'s eastern wing.>', `QuestDescription`) WHERE `ID` = 37519;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Golk\'s Lockbox', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Golk\'s Key to open Golk\'s Lockbox.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You lucky.$b$bYou can just break chain and walk out of cave.$b$bGolk get no chain. Golk just get teleported in by naga and get stuck if try to get out.$b$bNaga take Golk treasure box key. Golk not getting out any time soon. You want Golk treasure? You can have it.', `QuestDescription`) WHERE `ID` = 37529;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED]The Ancient One', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Approach Senegos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This place is now the home of what is left of the Blue Dragonflight. Its eldest dragon, Senegos, lies ahead within a pool of ley energy. If any are wise enough to help us find the Pillar of Creation that we seek on Azsuna, it will be him.$B$BStellagosa went ahead to join her grandfather. She assured me that we are welcome to enter the repose.$B$BCome, $n, we must hurry. Even from here, I can sense his life force waning. Let us approach him together.', `QuestDescription`) WHERE `ID` = 37691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mana Bark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Mana Bark.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need bark from the trees if we are going to fix the wood.$b$bBeing a mortal, you can walk right in and pick up the mana bark without any trouble, as long as you don\'t get eaten by something.$b$bCan you get us some mana bark?', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Sapphranosa at the Cerulean Overlook in Azsuna.', `QuestCompletionLog`) WHERE `ID` = 37843;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Essence of the Unbound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Unbound Essences.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need your help, mortal.$b$BSomething has warded the Mana Wood against our kind$b$bThat same something is changing the song of the wood. We can hear it.$b$bEnter the wood and gather essence from some of the local wildlife and maybe we can track this thing down.$b$bI will project an image of myself in the wood for when you are done.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with the Image of Azulos in the Mana Wood of Azsuna.', `QuestCompletionLog`) WHERE `ID` = 37844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rift Rippers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seal $1oa Unbound Rifts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something is opening rifts to the twisting nether using the ley line energy.$b$bThat is never a good thing.$b$bOur kind may not be able to enter the forest, but you can.$b$bTake this gem and look for these unbound rifts. The gem will let you seal these breaches.$b$bI will project an image of myself into the forest when you are done.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with the Image of Azulos in the Mana Wood of Azsuna.', `QuestCompletionLog`) WHERE `ID` = 37845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'About the Tidestone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place your hand upon Senegos\' horn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can sense it in your energy. You are here for the Tidestone.$b$bI have not spoken of the Tidestone of Golganneth in more than ten thousand years. I still remember that day. Cenarius was there... and Illidan, and...$b$b<The great dragon\'s eyes wince in pain, then re-focus.>$b$bI must rest my voice. Place your hand upon my horn, and I shall show you.', `QuestDescription`) WHERE `ID` = 37854;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whelp? That Happened.', `LogTitle`) WHERE `ID` = 37930;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar in the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$B|cFF600000                THE LEGION COMES!$B$B  THE MIGHT OF AZEROTH HAS FALLEN|r$B$BKing Varian Wrynn of Stormwind is dead. Warchief Vol\'Jin of Orgrimmar is missing in action.$B$BAny remaining heroes willing and able to defend our world should report to the Violet Citadel in Dalaran and speak to Archmage Khadgar and the Council of Six immediately!', `QuestDescription`) WHERE `ID` = 37962;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Yotnar the Giant', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Yotnor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So it is true... The great $n stands before me.$b$bI know what you are searching for. You want the pillar of creation, you seek the Aegis of Aggramar .$b$bFind the giant Yotnor. He will tell you the secrets of the vault.', `QuestDescription`) WHERE `ID` = 38016;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preserving The Lore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Stones of Remembrance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A cool breeze of thought and memory enters your mind as you touch the strangely glowing stone. Within an instant, the purpose of this stone has been made manifest.>nn<You realize that what you hold is a Stone of Remembrance; an object imbued with druidic knowledge and lore. The greedy Stoneblood harpies must have stolen these precious artifacts from the druids in Thas\'talah. You decide to search for more of these missing stones and return them to the Archdruid of Lore.>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to E\'lothir at Thas\'talah.', `QuestCompletionLog`) WHERE `ID` = 38218;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defending The Grove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Harpies involved in the attack on Thas\'talah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The harpies have had a presence in Val\'Sharah for hundreds of years. They have never been much more than an occasional nuisance; thus we have tolerated their presence here within these woods.$b$bHowever, something has emboldened them... it feels as though the forest is weakening... they must sense it as well.$b$bThe opportunistic harpies have broken the peace and attacked us in a time of weakness.$b$bHelp us defend Thas\'talah by slaying the invaders.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to E\'lothir at Thas\'talah.', `QuestCompletionLog`) WHERE `ID` = 38219;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeds of Remedy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Seeds of Remedy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Several of my fellow druids have been gravely wounded. Although my restorative abilities will keep them stabilized, there is still more we can do to aid them.$b$b<Aaelar produces a handful of glowing seeds from his pouch.>$b$bThese are efflorescent seeds imbued with the blessing of nature. If I had more of them, I could create a potion that would greatly aid in the recovery of the wounded.$b$bHarvest the efflorescent saplings that grow near the fountain of Delyra and I will prepare the potion.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Mender Aaelar at Thas\'talah.', `QuestCompletionLog`) WHERE `ID` = 38284;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Menacing Sprites', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa sprites in Thas\'talah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The local sprites are running amok and causing all sorts of problems!$b$bVal\'sharah is home to a variety of forest and pond sprites will take any opportunity to spread mischief and chaos. It seems as though an especially wicked group of sprites have descended upon Thas\'talah in the wake of the harpy invasion.$b$bThey are attacking the local wildlife and bullying the nearby faerie dragons. If you aid the local woodland creatures by taking care of the sprite menace, you will have our thanks.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Mender A\'aelar in Thas\'talah.', `QuestCompletionLog`) WHERE `ID` = 38285;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Worg Pelts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Heavy Worg Pelts from Hillstalker Worgs around Hreidshallr.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You know, it looks awful cold up there. If you plan on surviving your trip through those mountains, you should probably go prepared.$B$BYou\'ll find some worgs roaming the hills around here, and some of them still have their winter coats. Get yourself a few pelts to layer on while you\'re up there.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', '<insert>', `QuestCompletionLog`) WHERE `ID` = 38313;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blackbeak Overlook', `LogTitle`) WHERE `ID` = 38321;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halting the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy $1oa Nightmare Totems in the Moonclaw Vale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The corruption of the vale is the work of satyrs.$b$bThe new power they wield is unlike any I\'ve seen... it is dark, seething and terrible.$b$bNefarious demon totems help spread their taint upon the land.$b$bThe Nghtmare totems must be destroyed if we are to hold back the tide of corruption.', `QuestDescription`) WHERE `ID` = 38341;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rescued From Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save $1oa Prowler Cubs in The Midnight Vale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters.$b$bHowever, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale.$b$bI fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.', `QuestDescription`) WHERE `ID` = 38353;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eternal Battlefield', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Queen Ashildir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So, you seek to reclaim your soul?$b$bYou are fortunate, $r. The gaze of Helira is upon you.$b$bIf you can prove your might by defeating Helira\'s champion, Bloodbeard, Helira will consider letting your soul move on.$b$bIf you fail, your soul will be consumed, and like the others, you will be damned to an eternity on the battlefield.$b$bBloodbeard will not be defeated easily.$b$bPerhaps you should seek the counsel of Queen Ashildir. She is already on the battlefield. Although I doubt it will help.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to the Drifting Jarl at Arauk-Nashal in Helheim.', `QuestCompletionLog`) WHERE `ID` = 38364;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Disrupt Fel Rituals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Disrupt the fel rituals in the Thorignir Nest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons are using these circles to corrupt the Thorignir and twist them to their bidding. $B$BThese rituals should be stopped.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', '<insert>', `QuestCompletionLog`) WHERE `ID` = 38418;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bonus Objective: The Moonclaw Vale', `LogTitle`) WHERE `ID` = 38469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heart of a Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 10 Intact Thorignir Eggs and bring them to the Empty Nest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It looks like the minions of the God-King are stealing eggs from the Thorignir\'s nest. $B$BIf the future of these dragons is to be ensured, these should be returned.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', '<insert>', `QuestCompletionLog`) WHERE `ID` = 38520;
