UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aid For the Wounded', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Revive $1oa wounded allies by using the moonstone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] Many of our defenders have been gravely wounded on the battlefield. Take with you this moonstone and use it on our wounded allies on the battlefield. Heal their wounds and renew their courage against the forces of the enemy.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Lyanis Moonfall at the Temple of Elune.', `QuestCompletionLog`) WHERE `ID` = 38658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cleansing the Corruption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy $1oa Nightmare Totems on the Battlefield.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All along the battlefield, the satyrs have erected dark totems that spread the corruption of the Emerald Nightmare upon the land.$b$bAs long as the Nightmare totems remain, we will not be able to hold back the corruption!$b$bIf you truly wish to aid us in the fight, destroy the totems that you encounter upon the battlefield.$b$bOur survival depends on it!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Lyanis Moonfall at the Temple of Elune.', `QuestCompletionLog`) WHERE `ID` = 38660;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nightmare Bombs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Revive $1oa Nightmare Bombs on the Battlefield.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] The satyrs have taken to the skies on giant bats. From the air they rain down the corruption of the nightmare upon us.$b$bDisarm the nightmare bombs before they further corrupt the forest.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Isoraen Nightstar at the Temple of Elune.', `QuestCompletionLog`) WHERE `ID` = 38661;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Demon\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel with Archdruid Malfurion Stormrage.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xavius! How many times must I end that wretched satyr before he stays dead...$b$bWe must get to Shaladrassil and find Xavius before it is too late!$b$bMy wounds are grave, but they will heal... do not concern yourself with my safety. There is little time... we may already be too late...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Malfurion.', `QuestCompletionLog`) WHERE `ID` = 38667;
UPDATE `quest_template` SET `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Maiev Shadowsong in the Vault of the Wardens.', `QuestCompletionLog`) WHERE `ID` = 38669;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wormtalon Crone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Grelda the Crone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A wicked coven of harpies have overtaken our village.$b$bIt was the twisting of the forest that forced us out of our village, but now that the harpies have moved in I fear that we may never be able to return.$b$bThe Wormtalon coven are led by a witch called Grelda the Crone. She has made her nest in a cave near our village.$b$bIf their leader is defeated, the remaining harpies will surely flee.$b$bSlay Grelda the Crone and we will be forever in your debt, $c.', `QuestDescription`) WHERE `ID` = 38673;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Malfurion\'s Cure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Cleansed Mooncaps to Mender Onelle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The cleansed Mooncaps glow radiantly in your hands as you lift them from the waters of the ancient moonwell.$b$bMender Onelle will need the Mooncaps in order to make a healing poultice for Malfurion\'s wounds.', `QuestDescription`) WHERE `ID` = 38674;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hope Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Tear of Elune to Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.', `QuestDescription`) WHERE `ID` = 38688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED] Kill Feral Dogs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Anna Thornton at Barreltown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve done more than enough, $n. My people and I can clean things up here.$B$BYou should return to town and report on our victory.', `QuestDescription`) WHERE `ID` = 38693;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An End To War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Ironbranch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears that the great Ancient of War, Ironbranch, has fallen to the Nightmare.$b$bIt pains me greatly to ask this of you, but Ironbranch must be put to rest.$b$bIn life, he once stood vigil in Shala\'nir as a protector of the world tree. In death, my dear friend is no more than a destructive weapon that will be used to cause even more violence.$b$bHe must be slain before he does more harm to Val\'sharah.$b$bIn my heart, I know that he would thank you for this mercy...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to the Enduring Sapling.', `QuestCompletionLog`) WHERE `ID` = 38737;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hard Lessons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Burn 5 Harpy Nests and Break 5 Harpy Eggs in the Wretched Grove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please understand, stranger, that I am a being of peace. I have discarded any vengeful nature long, long ago.$b$bIn my youth, however, many hard lessons were learned through discipline. When applied wisely and properly, discipline can be a great teacher and shaper of character.$b$bIt is in the spirit of wisdom and guidance that I would have you teach these harpies a memorable lesson.', `QuestDescription`) WHERE `ID` = 38745;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inspiration Strikes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa vials of Leyblood, then bring them to Cedonu in Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blood of this creature glows with magical energy. It doesn\'t SEEM to be poisonous.$b$bYour training in the culinary arts has presented you with some strange ingredients before, but this one is particularly inspiring. Perhaps someone within the  Azurewing Repose can suggest a preparation for Leyblood.', `QuestDescription`) WHERE `ID` = 38867;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Revive Sea Dogs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '<insert>', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<insert>', `QuestDescription`) WHERE `ID` = 38875;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Extract Valkyra Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '<insert>', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<insert>', `QuestDescription`) WHERE `ID` = 38879;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aim to Misbehave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mark the Alliance caches for destruction by the Groghammer\'s cannons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These Alliance mongrels think they can infiltrate this place under our nose? We need to send them a message that Skold-Ashil is ours to siege!$B$BThe Groghammer has been trying to deliver that message with it\'s cannons, but the local mead tends to throw off the gunners\' aim. Maybe you can help.$B$BTake these flares and mark any Alliance caches you see amongst their forces. It should give a nice big target for the gunners to aim at.$B$BOh, and you might want to stand clear after planting the flare.', `QuestDescription`) WHERE `ID` = 38880;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Opportune Target', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Therese Castle in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This worgen operative\'s orders seem to be coming from one Therese Castle. nnIf she is leading this operation, then taking her out would deal a great blow to the Alliance\'s offensive efforts.', `QuestDescription`) WHERE `ID` = 38881;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Disable the Barrier', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '<insert>', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<insert>', `QuestDescription`) WHERE `ID` = 38883;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Defeat the Guardian', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deactivate the barrier and help Sylvanas recover the Discs of Eyir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have little time, $c. Even now, Greymane and his Gilneas Brigade are pressing their position in Skold-Ashild. We must retrieve the discs before our position is overrun!$B$BThe security console on the wall may have the controls to disable the barrier. See if you can deactivate it.', `QuestDescription`) WHERE `ID` = 38884;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist the warriors in killing the demon captains in the Fel Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Saurfang, Wyrmsbane, and Anselm could not wait for reinforcements, they have ventured into that mess to cut off the heads of demon captains. I\'m sure they do not require help but time is of the essence.$b$bIf you could go and assist them in killing the demon captains, we can get on with killing the portal guardian.', `QuestDescription`) WHERE `ID` = 38906;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Spiritwalker Ebonhorn in Thunder totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor.$b$bTo this end I have sent word for one of your allies to join us.$b$bWhen you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Spiritwalker Ebonhorn in Thunder totem.', `QuestCompletionLog`) WHERE `ID` = 38914;
