UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cleansing the Fountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Cleanse the demon blood from the fountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blood from an impaled dreadlord is flowing into a fountain at the base of Valhallas. Following orders given by their "God-King" the vrykul are drinking from the fountain. nnThe demon blood is driving the vrykul mad and it\'s giving them greater power than they deserve.$B$BTake this acorn. Throw it into the fountain. My ravens will take care of the rest.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'xxxx', `QuestCompletionLog`) WHERE `ID` = 39126;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The New Chieftain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Mayla Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So you are the one of whom Ebonhorn foretold. I thought you would be taller.$b$bOur High Chieftain Ulan has been slain by the drogbar when they seized the hammer.$b$bHis daughter, Mayla Highmountain, has now taken on the burden of High Chieftain.$b$bYou can find her on the northern bluff with what few forces we have left to defend this place.$b$BShe will have need of you.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Mayla Highmountain on the northern bluff of Thunder Totem.', `QuestCompletionLog`) WHERE `ID` = 39132;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Sundered Tribe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the Rivermane, Bloodtotem, and Skyhorn chieftains.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dargrul didn\'t just take the Hammer of Khaz\'goroth. He slew the High Chieftain -- my father -- to get it.$b$bThere are some who claim our tribe died with my father, and they have gone their separate ways.$b$bBut you... you look like someone they might listen to. You might convince them to return or at least send reinforcements.$b$BCan you speak with the representatives of the three tribes?', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Mayla Highmountain in Thunder Totem.', `QuestCompletionLog`) WHERE `ID` = 39135;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forging the Artifact', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Valgar\'s anvil to imbue your artifact with a new power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve certainly got our work cut out for us, but not to worry. There\'s nae weapon in existence that ye can\'t improve, legendary ones included!$B$BThis anvil\'s only powerful enough to imbue your artifact once before we\'ll need something better, but that\'ll have to do fer now.', `QuestDescription`) WHERE `ID` = 39151;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lynore\'s Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lynore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears Eira has a present for you, your first valarjar! You lead \'em, I\'ll make sure their weapons and armor are ready for war!', `QuestDescription`) WHERE `ID` = 39200;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Twisted Garden', `LogTitle`) WHERE `ID` = 39205;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Never Alone', `LogTitle`) WHERE `ID` = 39269;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Zephyrus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon and defeat Zephyrus of Phoenix Peak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Crawliac harpies are too numerous and too well prepared for our normal tactics.$b$bWe need a champion to call forth Zephyrus, the great wind spirit of Highmountain.$b$bHigh Crawliac won\'t see that coming!$b$bJourney to the top of Phoenix Peak and sound the great Skyhorn. When Zephyrus comes, defeat him in battle to prove your worthiness.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with the Zephyrus of Phoenix Peak', `QuestCompletionLog`) WHERE `ID` = 39319;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Mysterious Summons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Havi outside of Aggramar\'s Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$C, heed my call. I am aware that you come to Stormheim seeking the Aegis of Aggramar. nnKnow that this will be a monumental task.$B$BHowever, I see promise in you, and thus will guide you through the ancient trials. I must warn you that no mortal has passed even the first of these trials in the recorded history of Stormheim, though countless champions have tried.$B$BIf you believe yourself worthy, outsider, seek me outside Aggramar\'s Vault. Your first test will await you there.', `QuestDescription`) WHERE `ID` = 39589;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harbingers of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gaze into the Pool of Judgement.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, you must stop this argument before the damage is irreparable.$B$BKayn and Altruis must be reminded of their common bonds.$B$BThe Pool of Judgement can reflect memories of the past. Touch it, and draw upon your own recollections. nnRemind them what it meant to fight under Lord Illidan. Remind them why we took the demon hunter\'s path.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Cassiel Nightthorn at the Vault of the Wardens.', `QuestCompletionLog`) WHERE `ID` = 39687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Path of Huln', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Spiritwalker Ebonhorn on the Path of Huln.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar have a tool of the titans in their possession, and it falls to us to find a way to get around that.$b$bTo that end, I recommend we walk the Path of Huln to the place our people first recovered the hammer so many generations ago.$b$bI have asked for the aid of Brann in this endeavor as there are few in the living world more acquainted with titan artifacts.$b$bThe road is dangerous, and we could use your aid upon it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Spiritwalker Ebonhorn at Neltharian\'s Vault.', `QuestCompletionLog`) WHERE `ID` = 39693;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Walrus Tusks', `LogTitle`) WHERE `ID` = 39785;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Collect Weapons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '<insert>', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<insert>', `QuestDescription`) WHERE `ID` = 39852;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Curse of the Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free cursed vyrkul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] <You find a strange glowing orb inside the treasure chest. A commanding voice emits from the orb-- it is Odyn.> nnVery good, $n, you\'ve found my orb. The souls of vrykul champions are unrightfully being transported to Helheim. These champions deserve a place in Valhallas, not an eternity alongside that witch.$B$BUse this cleansing orb on the cursed vrykul to free them. If the ship reaches the shores of Helheim before the curse is lifted, they will be doomed to serve an eternity as Helya\'s kvaldir.', `QuestDescription`) WHERE `ID` = 39854;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meet the Recruits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Guiding Light spell to return to Light\'s Hope Chapel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord, my mission in Dalaran was successful. I have recruited paladins truly worthy to carry your banner.$B$BThey await your return at the Sanctum of Light.', `QuestDescription`) WHERE `ID` = 39978;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DEPRECATED', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar sent word about Val\'Sharah not long ago.$B$BHis Kirin Tor have opened a gateway between here and Dalaran - you can find it in the alcove behind you if you wish to make use of it, Highlord.', `QuestDescription`) WHERE `ID` = 39979;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keepers of the Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet the High-Chieftain at Thunder Totem in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'High Chieftain Ulan has requested your presence.$b$bWe have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid.$b$bOur people have in our possession a great titan relic: the Hammer of Khaz\'goroth.$b$bWe intend to lend it to you for this task.$b$BWhen you are ready, join me at our stronghold of Thunder Totem in Highmountain.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Mayla Highmountain at Thunder Totem.', `QuestCompletionLog`) WHERE `ID` = 39989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DEPRECATED: Assignment: Archmage', `LogTitle`) WHERE `ID` = 40098;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DEPRECATED: Getting Back to Business', `LogTitle`) WHERE `ID` = 40101;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disrupt the Inkbinders', `LogTitle`) WHERE `ID` = 40110;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Titanic Showdown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and aid the spirit of Huln Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The greatest time scar of all is just ahead.$b$bKhaz\'goroth was the titan who shaped the world. Using his hammer against Deathwing, the aspect of earth, had dire consequences.$b$bGo, speak with Huln and witness the reason why the name "Highmountain" is feared amongst dragons to this day.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Huln Highmountain in Neltharian\'s Vault.', `QuestCompletionLog`) WHERE `ID` = 40311;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felsoul Hold', `LogTitle`) WHERE `ID` = 40420;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felsoul Slag', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect dragon\'s breath from the dragons inside Neltharion\'s Vault in Highmountain. Acquire a crucible from the mystic area of Haustvald in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jabrul\'s tribe is known for making a gem called the Saber\'s Eye. Different jewels are gathered together and, with our combined strength, melted into a single, brilliant stone.$b$bThe tribe is not here, but with hot enough flame, a Saber\'s Eye could still be forged.', `QuestDescription`) WHERE `ID` = 40554;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Amassing Gems', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you know how to make a Saber\'s Eye, what sort of design would you like to cut it into?$b$bJabrul can show you one of the ones he knows.', `QuestDescription`) WHERE `ID` = 40555;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warrior Inbound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Skyjump to Halls of Valor to return to your order hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Skylord, the mission to Dalaran was successful. The warrior awaits your return at the Halls of Valor.', `QuestDescription`) WHERE `ID` = 40590;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Mouth of the Nether', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escape from Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the ritual failed and the council scattered, you find yourself trapped in the prison of the pit lord, Jagganoth.$B$BThe situation is grim, but with the help of the remaining council members, you may be able to escape.', `QuestDescription`) WHERE `ID` = 40685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Xalethar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Track and slay Xalethar in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The satyr known as Xalethar has been sighted near the Den of Dreams in Val\'sharah.$b$bSeveral reports have come in regarding demon activity in that area. I want you to go and investigate.$b$bSearch for Xalethar near the Den of Dreams and slay him without mercy.', `QuestDescription`) WHERE `ID` = 40700;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blackroot Idols', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Narla\'s Branch from Chieftain Narla and Drawzle\'s Bough from Drawzle Keen Eye in the Blackroot Village.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Blackroot are lead by Chieftain Narla.$BI fear that her mind has become twisted beyond reason.$B$BI attempted to make peace with the Blackroot, but I quickly retreated when Drawzle Keen Eye let loose a volley of arrows. I was fortunate enough to escape unharmed.$B$BThis tribe is lost and Narla and Drawzle must be dispatched before the Blackroot spread like a blight. Return their weapons to me as proof of their demise.', `QuestDescription`) WHERE `ID` = 40769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keeper\'s Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Blackroot furbolgs in Blackroot Village.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Blackroot have become savage and aggressive. The confluence of energy in this area was simply too much for these furbolgs to handle.$B$BI have tried to soothe their minds, but my efforts have all ended in violence. There is little else that can be done, $r.$B$BThey must be cut down to protect the neighboring lands.', `QuestDescription`) WHERE `ID` = 40770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wild By Nature', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 4 Blackroot Totems in the Blackroot Village.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Furbolgs often empower totems to harness their natural power and ward off enemies.$B$BUnfortunately, due to the malicious nature of the Blackroot, their totems are tainting any poor creature that comes near them,$B$BWe can\'t allow others to be corrupted by their totems.', `QuestDescription`) WHERE `ID` = 40771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trophy Hunting', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Redtooth and return its head to Mom\'zula at the <hunting camp>.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dat Hemet Nesingwary think he be such a great hunter. When we ask to join his hunt, he laugh at us and turn us away. We show him who da best hunter really be.$B$BOnly thing, mon, we be needin\' your help.$B$BRedtooth be da most dangerous prey in the area. I\'d hunt it myself, but those pale creepers be all over da place.', `QuestDescription`) WHERE `ID` = 40775;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vittles and Bits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Tony Mordain\'s Cleaver to carve Animal Bits from the wildlife near the <hunting camp>.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I used to travel the world until I fell in with this lot of incompetent hunters. When I found them, they were practically starving to death.$B$BI cooked one meal for them, and somehow became their camp cook.$B$BIf you\'re going out into the wild, bring me back some animal parts that I can cook up for this lot.', `QuestDescription`) WHERE `ID` = 40777;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Impaired', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Tend to any of Mom\'zula\'s Hunters that you find outside of the <hunting camp>.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Kalla motions for you to come closer and whispers.>$B$BI do not want Mom to hear, but as you can probably tell by all the wounded, these hunters are not very skilled. They are more likely to twist an ankle than they are to track down a lame deer.$B$BI cannot be everywhere at once. If you come across any of our band in the wilds, please tend to them.', `QuestDescription`) WHERE `ID` = 40780;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Relief For Parim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Fragrant Poppies for Parim Eversong outside of the <hunting camp>.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The air around these flowers is sweet and crisp.$B$BParim Eversong would welcome the pleasant smell of these flowers.', `QuestDescription`) WHERE `ID` = 40782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Withered and Creeping', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Withered around the <hunting camp> for Mom\'zula.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen those pale creepers, mon? I\'ve seem \'em lurching about outside da camp.$B$BThey be scarin\' away our game and makin\' us look bad.$B$B<Mom\'zula leans in and whispers.>$B$BThey also make my skin crawl. I bet dat even Hemet would turn hide and run if he saw one.$B$BI\'m tellin\' ya, mon. They be bad voodoo.', `QuestDescription`) WHERE `ID` = 40788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Struggle Of Power', `LogTitle`) WHERE `ID` = 40790;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meet The Master', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Zen Pilgrimage spell to return to the Wandering Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey there $ct, my mission in Dalaran was a complete success! This new monk is really strong and would be great to have as part of the order!$B$BWe will be waiting for you back at the Wandering Isle.', `QuestDescription`) WHERE `ID` = 40805;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arcano-Plasm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 20 Arcano-Plasms from Arcano Pools or from dead Arcano Slimes in the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey there, friend. I am in a bit of a bind and I was hoping that you could lend me some assistance.$B$BI was studying the nearby ley line that runs through this area. Well, I was paying close attention to my scanners, but not to my fuel gauge.$B$BI managed to put down my gyro safely, but I\'m out of fuel.$B$BAccording to my scans, there are deposits of Arcano-Plasm in this tunnel, which I can convert into fuel.$B$BYou\'ll need this Arcane-Drano to extract the samples.', `QuestDescription`) WHERE `ID` = 40806;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing the Tunnels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Feeble Husks in the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The nearby  tunnel runs right along the very ley line that I\'ve been studying from the sky. It\'s a happy coincidence that I landed at this very spot, don\'t you think?$B$B<Nedward frowns a bit.>$B$BWell, it would haven been, but it seems that the ley line has also attracted every withered creature in Suramar.$B$BCould you lend me a hand and get them to scoot?', `QuestDescription`) WHERE `ID` = 40807;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fuel Transfer Worker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve FTW-001 from the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I knew that I could extract fuel from the Arcano-Plasm, but after getting an eyeful of all those withered creatures running about, I decided to send my Fuel Transfer Worker to collect the samples. I call him FTW-001 for short.$B$BUnfortunately, FTW-001 never came back out and I there\'s no way in Gnomeregan that I am going in after it.$B$BKeep an eye out for it if you go in there, would ya?', `QuestDescription`) WHERE `ID` = 40808;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not to Scale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 100 Mistbreaker Scales from Mistbreaker naga <naga area>.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was looking for my husband when I accidentally stumbled on this group of naga.$B$BOne of those large brutes nearly crushed me with his foot, but I ran and hid in this cage for protection.$B$BIf I am going to get out of here with my life, I\'ll need a disguise. I have the know-how, but I need the components. That\'s where you come in.', `QuestDescription`) WHERE `ID` = 40811;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trident True', `LogTitle`) WHERE `ID` = 40812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It\'s in the Glands', `LogTitle`) WHERE `ID` = 40813;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arcano-Plasm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 20 Arcano-Plasms from Arcano Pools or from dead Arcano Slimes in the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You got time to give a goblin a hand? Good, thought so.$B$BI was flying my rocket and taking readings of this ley line, you see. Only I wasn\'t keeping an eye on my fuel reserves. Long story short, I ran out of gas.$B$BI set it down safely and all, but I don\'t have enough fuel to get me outta here. There\'s a nearby cave filled with Arcano-Plasm, which I can use to fuel my rocket. Wanna get some for me?$B$BOh yeah, you\'ll need this here Arcano-Drano to extract it.', `QuestDescription`) WHERE `ID` = 40825;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing the Tunnels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Feeble Husks in the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before I went down, I was tracing the nearby ley line. Turns out, it goes right by the nearby caves.$B$BI\'d like to get down there for a closer look, but that ley line is attracting every withered from here to Azsuna.$B$BBut hey, you look like a strong $r. I bet you\'d have no problem clearing them out of there. It\'s just like trying to clear rats out of a sewer.$B$BWell, sort of.', `QuestDescription`) WHERE `ID` = 40827;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fuel Transfer Worker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve FTW-001 from the Arcano Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m no dummy, $n. I let my brains do the work for me. When I landed, I sent in my personal Fuel Transfer Worker to gather up the Arcano-Plasm.$B$BI call it the FTW-001. Great name, right? Well anyway, the darn thing never came back with my Arcano-Plasm.$B$BI ain\'t about to go chasing after it with all of those withered things running about.$B$BIf you come across the FTW-001, would ya let me know? I\'ll even throw in a few coins for your trouble.', `QuestDescription`) WHERE `ID` = 40828;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Save the Crumbling Coast', `LogTitle`) WHERE `ID` = 40831;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mograine\'s Recruit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Death Gate spell to return to Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Suffer well $ct, my mission in Dalaran was a complete success!$b$bWe will await your arrival at Acherus.', `QuestDescription`) WHERE `ID` = 40833;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Aid of Val\'sharah', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Raj\'kess and Overseer Sakar\'thiss in the Crumbling Coast.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The land is in pain, $n, and we have felt its suffering. The druids of Val\'sharah will not stand idly by and let our ancient home fall to ruin at the hands of the Leyspine naga.$B$BOur charge is to protect nature. These naga seem only to want to destroy it. We must cut down their leaders and drive back their forces.$B$BWith you help, $n, we may still be able to save this land.', `QuestDescription`) WHERE `ID` = 40841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Coastal Healing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Seed Pouch to plant 8 seeds in Sinkholes in the Crumbling Coast.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The earth has suffered wounds at the hands of the Leyspine naga. They have subjugated murlocs to tear up the land and extract its resources for their own devices.$B$B<Lyris hands you a pouch of seeds.>$B$BI have infused these seeds with restorative essences. Place a seed in any scar left by the murlocs and the healing can begin.', `QuestDescription`) WHERE `ID` = 40845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Foe Underestimation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Cromlechus in the Ancient Well.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The scroll is written in an elegant script.>$B$BWith the arrival of the Legion, we will be expanding our territory far beyond the confines of Suramar.$B$BYou are to enter the ruins underneath Featherfall Village and dispose of any and all creatures that are inhabiting it.$B$BTake heed. Our scouts have reported many creatures roaming its ancient halls, including a large crystalline giant.$B$BReport back to Suramar after the ruins are clear.', `QuestDescription`) WHERE `ID` = 40848;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkwell\'s Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 20 Crystallized Mana Cores from creatures in Featherfall Ruins or the Ancient Well.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When I was exiled from Suramar, I tried all manner of things in order to sustain myself.$B$BMany of the creatures that reside in these ruins contain traces of Ancient Mana, but have converted into a crystalline form that is useless to me.$B$BAs chance would have it, Manashale loves to eat this crystallized mana. When he is, uh, done digesting it, the results are turned into a form that I can use.$B$BIf you have any of this crystallized mana on you, I\'d sure like to have it.', `QuestDescription`) WHERE `ID` = 40851;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Corrupted Into Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Corrupted Sisters in the Ancient Well.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$C, We need your help!$B$BWe came here from Val\'sharah to lend aid to our sisters against the Legion. When we arrived, we found that they had been corrupted by the arcane energies that flow through these ruins.$B$BBefore we could act, our corrupted sisters attacked us. Those of us that remain have been backed into this corner. Here we must make a final stand.$B$BIf we are to survive this onslaught, we will need to fight our way out.', `QuestDescription`) WHERE `ID` = 40884;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Transplanting Their Cores', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Pristine Shalebark Cores from Shalebark Treants in the Ancient Well.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All dryads have a connection with nature, $n. We live to nurture all living things. Even in their corrupted state, our sisters are fostering the growth of the plants in these ruins.$B$BSadly, these plants are feeding off of the corruption that has taken over.$B$BThe Shalebark have a natural resistance to this corruption. If their cores have not been tainted, there still is a chance to cleanse and replant them elsewhere.$B$BOf course, that assumes that we escape with our lives.', `QuestDescription`) WHERE `ID` = 40885;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Verdant Search', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Apply Leafwind\'s Salve to 6 Injured Verdant Watchers in the Ancient Well.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Corrupted Sisters set upon us, many of the Watchers fell behind when we fled. Few made here it, and fewer have the ability to fight.$B$BWe cannot let the Watchers die in this accursed place, but we don\'t have the strength to go into the ruins and retrieve them.$B$BThis is a task that I must ask of you.$B$BUse this salve to treat the wounds of any Watcher that still draws breath.', `QuestDescription`) WHERE `ID` = 40886;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Honor Among Thieves', `LogTitle`) WHERE `ID` = 40992;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rendezvous', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Extraction Point ability to return to the Hall of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct $n, the recruitment operation was successful.$B$BRendezvous in the Hall of Shadows as soon as possible to debrief.', `QuestDescription`) WHERE `ID` = 40998;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Agent of Aid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Alonsus and his friend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see old Alonsus there giving us the eye. That man never sleeps, literally! And now neither will you, heh.$b$bGo on then, looks like he wants to introduce you to someone.', `QuestDescription`) WHERE `ID` = 41018;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Forge of Guardians', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Meryl and Alodi transport the Forge of the Guardian to a safe location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'First and foremost, the Forge of the Guardian must be protected. With Kathra\'natir\'s knowledge, it will no longer be safe in Violet Hold.$B$BTogether, we should be able to transport it to a safer place. From there, our true challenge can begin.', `QuestDescription`) WHERE `ID` = 41058;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troubling News', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Sanctum Crystal to enter the Master\'s Sanctum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Master, there is one more thing I wish to speak to you about.$B$BBelow us lies an open chamber cut off from the rest of the citadel. We thought you might desire it as your personal sanctum - a place where you might gather your thoughts or scry upon your enemies.$B$BThe sanctum crystal before you will transport you there - Lady S\'theno has already descended to help you get acquainted.', `QuestDescription`) WHERE `ID` = 41065;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lady S\'theno Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Gateway: The Fel Hammer ability to return to the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Master $n, I have completed my reconnaissance in Dalaran as you asked.$B$BI await your return at the Fel Hammer.', `QuestDescription`) WHERE `ID` = 41101;
