UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Other City of Mages', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission The Other City of Mages at your [PH] Command Table in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Akazamzarak should be back from Dalaran with a new recruit to the Tirisgarde.$B$BThey await your return at the Hall of the Guardian.', `QuestDescription`) WHERE `ID` = 41147;
