UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free both Altruis the Sufferer and Kayn Sunfury.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We cannot fight our way out of the Vault alone.$B$BTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. nnFree them with haste. Their strength will be of great use to us.', `QuestDescription`) WHERE `ID` = 41226;
