UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mead Master', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Apprentice Meldir in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The vyrkul meadery overlooks the coast in northern Stormheim. Meet me there when you are ready, $n.', `QuestDescription`) WHERE `ID` = 41873;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tainted Growth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Corrupted Seedlings and return them to Tyrande.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blood red petals of the Nightmare Flower seethe with chaotic energy. The plant twitches every now and then, releasing puffs of pollen into the air. nnThe nearby satyrs and keepers can be seen harvesting similar plants for little crimson seeds.$B$BThese seeds must be destroyed.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Tyrande.', `QuestCompletionLog`) WHERE `ID` = 41891;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gathering the Pieces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Mission Table and complete five Order Hall missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Grand Master, the Mission Table is now at your disposal.$B$BThere are several strategic areas where we can focus our Order\'s efforts.$B$BFirst, we should check on the status of the other monk temples. It seems the Legion has a special focus on destroying us.$B$BSecond, we need to scour the seas near the Broken Shore. There are still many missing from the battle.$B$BFinally, there is the continued appearance of demonic forces at numerous points across the Broken Isles. They must be kept at bay.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Iron-Body Ponshu at the Temple of Five Dawns.', `QuestCompletionLog`) WHERE `ID` = 41903;
