UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kept Secret, Kept Safe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kalec at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the scrolls in hand, now you must set to the task of finding the staff.$B$BWhen Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.$B$BThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.', `QuestDescription`) WHERE `ID` = 42003;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gift of Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Meryl Felstorm in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done a great thing for the blue dragons today, $n, as well as for my own peace of mind.$B$BNow, armed with Aluneth, I only ask that you fulfill your original goal, and take the fight to the Legion.$B$BI believe your comrades await your back in the Hall of the Guardian. Safe travels, friend.', `QuestDescription`) WHERE `ID` = 42012;
