UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Ancient Elemental Altar to imbue your artifact, then speak to Advisor Sevel at the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears you & your weapon are both growing in strength. Return to me at the Heart of Azeroth. I have more to show you.', `QuestDescription`) WHERE `ID` = 42379;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unholy Destiny', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the Grimoire of Damnation.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The greatest heroes on Azeroth have gathered together to face the Burning Legion. But heroes alone cannot save this world.$b$bThe salvation of Azeroth will come at a price the living cannot pay. Only upon the shoulders of the dead and damned, will the world of the living be spared.$b$bYou shall be their pariah, $n. Find the Grimoire of Damnation and do what must be done.', `QuestDescription`) WHERE `ID` = 42448;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Blaze of Starlight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Tidestone of Golganneth to Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will deliver the good news of my recently-rediscovered vitality to my brood. You, on the other hand, have a Tidestone to deliver.', `QuestDescription`) WHERE `ID` = 42566;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Felblood Altar to imbue your artifact, then speak to Calydus in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend is getting stronger, and so is friend\'s weapon! Come back to Dreadscar. I have more to show you.', `QuestDescription`) WHERE `ID` = 42600;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Felblood Altar to imbue your artifact, then speak to Calydus in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend is getting stronger, and so is friend\'s weapon! Come back to Dreadscar. I have more to show you.', `QuestDescription`) WHERE `ID` = 42613;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use The Forge of the Guardians to imbue your artifact, then speak to Meryl Felstorm in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see you have grown in strength. With it, some of the untapped potential within your weapon is released.$B$BCome back to the Hall of the Guardian when you are done with your adventures, and I will show you more.', `QuestDescription`) WHERE `ID` = 42672;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Banner of the Ebon Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place 8 Banners of the Ebon Blade to inspire your troops.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Although the Scarlet Crusade are murderous zealots, the monastery is still blessed by the Light. This places us at a disadvantage.$b$bThe battle for the Scarlet Cathedral will be hard fought, Deathlord.$b$bWith you fighting alongside our brothers and sisters of the Ebon Blade, they will surely be inspired to victory.$b$bTake up the banner of our order and place it near our troops to empower them.$b$bNot even the Light will stop us from our goal!', `QuestDescription`) WHERE `ID` = 42822;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pure Water', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 10 Pure Water from naga and water elementals in the Eye of Azshara dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I may have discovered the key to restoring the pillar\'s magical energy.$B$BFirst, we will require a great deal of Pure Water. It is not easy to find, however I have heard that the naga in the Eye of Azshara are known to carry large quantities of this concentrated essence.$b$bIt will be not be easy, but if you can collect enough of the essence, we may be able to restore the pillar.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Elementalist Janai at the Heart of Azeroth.', `QuestCompletionLog`) WHERE `ID` = 42981;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Altar of Light and Shadow to imbue your artifact, then speak to Betild Deepanvil in Netherlight Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears ye and yer weapon are both growin\' in strength. Return to me at Netherlight Temple. I have more to show ye.', `QuestDescription`) WHERE `ID` = 43260;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Soul Forge to imbue your artifact, then speak with Highlord Darion Mograine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The bond between you and your weapon has grown stronger, Deathlord. The time has come for you to direct the flow of power within your artifact.$b$bReturn to Acherus and speak with me when you have made your choice.', `QuestDescription`) WHERE `ID` = 43263;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pixie Dust', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Arkhana to Brightwing. Arkhana is obtained through the enchanting profession.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend, you have done so much for Brightwing, but there is still so much more to do.$B$BI\'ve been working so hard to restore the grove, but my magic is drained.$B$B<Brightwing\'s stomach grumbles loudly.>$B$BWithout magic, my work cannot continue. The enchanters of your people use a magical dust that can revitalize me quickly.$B$BIf you bring me some, I can work much faster!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Brightwing at the Emerald Dreamway.', `QuestCompletionLog`) WHERE `ID` = 43367;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Second Weapon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give 300 Order Resources to Meryl to push forward research on other artifacts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see the Legion hasn\'t taken a bite out of you yet. It seems like that weapon is working out quite well.$B$BOur researches and scryers have been keeping a wary eye out on the other ancient weapons out there, mostly to make sure they don\'t fall into the hands of the Legion. But we could seek another to wield if you see fit.$B$BIn the meantime, the researchers are in desperate need of more resources. If you find enough to spare, I will see to it that they go to the right place.', `QuestDescription`) WHERE `ID` = 43439;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Building on the Knowledge of Our Elders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the 4 ancient conpendiums requested by your head researcher.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings to you, $n.$B$BWe\'ve made great strides in uncovering knowledge about your weapon, but if we truly want to learn what it\'s capable of, we need to get our hands some texts that are... let\'s just say they\'re hard to come by.$B$BI can\'t emphasize enough how important this research will be to unlocking the remaining power within your weapon. If you can bring these tomes back to me, I promise you it will be well worth the effort.', `QuestDescription`) WHERE `ID` = 43466;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Satisfy Thrymjaris\' demands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You bring the cursed bindings of Ragnaros to this place. Speak your intent, $r.', `QuestDescription`) WHERE `ID` = 43559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Illiana Dreadmoore\'s notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Any death knight worth their salt knows the weapon they wield as if they were born with it.  But you now carry a weapon older than any in this hall.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. Research is not a glorious task, and is certainly unworthy of the Hand of the Lich King. I will do this for you.$B$BIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Vehu\'s notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A demon hunter is nothing without blades with which to cut flesh. Yet those you wield are older than even you... and have power we don\'t understand yet.$B$BIf you truly want to unlock all of their potential, we need to learn more about them. Research is not a glorious task, and is certainly unworthy of the Hand of Illidan. I will do this for you.$B$BIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Celadine\'s notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. That\'s where I come in. It\'s my specialty.$B$BBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43818;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the scouting notes to locate and recover the 4 ancient tomes Lorewalker Cho needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. I am quite good at such things.$B$BBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I had one of the initiates attempt to find them. Here are her notes.', `QuestDescription`) WHERE `ID` = 43820;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Sister Elda\'s notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a might weapon with a long history, one we barely understand.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. I can get workin\' on that for ya.$B$BBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I put one of the researchers on digging up where they might be. Here are her notes.', `QuestDescription`) WHERE `ID` = 43821;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Juvess\' notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. I can do this for you.$B$BBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43822;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Fillius\' notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your weapons are undeniably powerful, but we know near nothing about\'m.$B$BIf we want to unlock all of their potential, we need to dig up some dirt on how they work, what they\'ve done... get to know them, ya know? That\'s where I come in. I dig up dirt all the time. I mean, not literally, but... you know what I mean.$B$BBefore I can get started though, I need some books. Some important ones. They may be hard to pinch. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43823;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Gorma\'s notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. We know stories of it, but little about its origins.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. The winds can help us with this, but we need to know what to ask.$B$BI know of a few books that will give me the right place to start. They may be hard to get your hands on, but they\'ll be worth it. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43824;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Mile\'s notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it.$B$BIf we truly want to unlock all of its potential, we need to learn more about it. That is a thing that I can do for you.$B$BBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I\'ll give you my notes to help you find them.', `QuestDescription`) WHERE `ID` = 43825;
