UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Needs of the Many', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the Kirin Tor mages in Orgrimmar and travel to Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve seen that the Legion is everywhere. Even with the Illidari as your allies, we are at a great disadvantage.$b$bWe need an edge against the Legion... something to send them back to the Nether.$b$bWe have heard that Dalaran will be the focal point of our campaign. I suggest you go there. You must do anything necessary to become stronger. ANYTHING.$b$bI have seen Kirin Tor mages near Grommash Hold. They can send you to Dalaran.$b$bGo. Take revenge upon the Legion!', `QuestDescription`) WHERE `ID` = 44091;
